(window.CARDS = window.CARDS || {}).film = [{"name":"Крёстный отец","emoji":"🍊","meta":["криминальная драма","1972","Фрэнсис Форд Коппола"],"description":"О сицилийской мафиозной семье Корлеоне в Нью-Йорке 1940-х, где на смену стареющему дону приходит его младший сын. Экранизация романа Марио Пьюзо стала эталоном гангстерского кино и разошлась на цитаты.","fact":"Фраза «Я сделаю ему предложение, от которого он не сможет отказаться» вошла в число самых известных в истории кино.","wiki_en":"The Godfather"},{"name":"Побег из Шоушенка","emoji":"⛓️","meta":["драма","1994","Фрэнк Дарабонт"],"description":"История банкира, несправедливо осуждённого за убийство жены и отправленного в суровую тюрьму, где он находит опору в дружбе с сокамерником. Экранизация повести Стивена Кинга долгие годы держится на первом месте в зрительском рейтинге IMDb.","fact":"В прокате фильм провалился, но стал одним из самых пересматриваемых благодаря повторным показам по телевидению и видео.","wiki_en":"The Shawshank Redemption"},{"name":"Криминальное чтиво","emoji":"💼","meta":["криминальная комедия","1994","Квентин Тарантино"],"description":"Несколько переплетённых историй из жизни бандитов, боксёра и парочки грабителей в Лос-Анджелесе, рассказанных не по порядку событий. Фильм прославился рваной нелинейной структурой, дерзкими диалогами и саундтреком, а также вернул на большие экраны Джона Траволту.","fact":"Содержимое светящегося чемоданчика в фильме так и не показывают — зрителям предлагают додумать его самим.","wiki_en":"Pulp Fiction"},{"name":"Форрест Гамп","emoji":"🍫","meta":["драма","1994","Роберт Земекис"],"description":"Простодушный парень из Алабамы случайно оказывается участником ключевых событий американской истории второй половины XX века. Фильм соединяет наивный юмор с ностальгией и стал одним из самых цитируемых в поп-культуре.","fact":"Фраза Форреста про коробку шоколадных конфет — «никогда не знаешь, что тебе попадётся» — стала расхожей идиомой.","wiki_en":"Forrest Gump"},{"name":"Матрица","emoji":"💊","meta":["фантастика","1999","Вачовски"],"description":"Хакер узнаёт, что привычный мир — это компьютерная симуляция, а настоящая реальность выглядит совсем иначе, и присоединяется к восстанию против машин. Фильм произвёл революцию в визуальных эффектах благодаря технике «пуля-тайм» и задал моду на чёрные кожаные плащи.","fact":"Выбор между красной и синей таблеткой из фильма превратился в устойчивый культурный образ выбора между удобной ложью и неприятной правдой.","wiki_en":"The Matrix"},{"name":"Бойцовский клуб","emoji":"🧼","meta":["драма","1999","Дэвид Финчер"],"description":"Безымянный офисный работник, страдающий от бессонницы и апатии, знакомится с харизматичным торговцем мылом и вместе с ним организует подпольные бойцовские клубы. Экранизация романа Чака Паланика поначалу разочаровала критиков, но со временем обрела статус культового фильма.","fact":"Первое правило Бойцовского клуба в фильме — никому не рассказывать о Бойцовском клубе — стало устойчивым мемом далеко за пределами кино.","wiki_en":"Fight Club"},{"name":"Начало","emoji":"🌀","meta":["фантастика","2010","Кристофер Нолан"],"description":"Специалист по проникновению в чужие сны получает задание не украсть идею, а наоборот — незаметно её внедрить, спускаясь для этого на несколько уровней сновидений одновременно. Сложная структура фильма с вложенными снами и открытым финалом породила споры зрителей.","fact":"Волчок, который герой крутит на протяжении фильма, стал символом неоднозначности финала — каждый решает сам, остановился он или нет.","wiki_en":"Inception"},{"name":"Интерстеллар","emoji":"🚀","meta":["фантастика","2014","Кристофер Нолан"],"description":"Из-за экологической катастрофы человечество на грани вымирания, и бывший пилот отправляется через червоточину искать пригодную для жизни планету, оставляя дочь на Земле. Фильм известен научной консультацией физика Кипа Торна и визуализацией чёрной дыры.","fact":"Из-за эффектов замедления времени рядом с чёрной дырой один час на далёкой планете в фильме равен годам на Земле.","wiki_en":"Interstellar (film)"},{"name":"Тёмный рыцарь","emoji":"🦇","meta":["боевик","2008","Кристофер Нолан"],"description":"Бэтмен, комиссар Гордон и прокурор Харви Дент пытаются остановить анархиста-преступника по прозвищу Джокер, который бросает вызов всем правилам Готэма. Фильм переосмыслил супергеройское кино как мрачный криминальный триллер и получил признание критиков.","fact":"Посмертный «Оскар» за роль Джокера получил Хит Леджер, умерший до премьеры фильма.","wiki_en":"The Dark Knight"},{"name":"Властелин колец: Братство Кольца","emoji":"💍","meta":["фэнтези","2001","Питер Джексон"],"description":"Хоббит Фродо получает опасное поручение — уничтожить Кольцо Всевластия, и вместе с разношёрстным отрядом отправляется в долгий путь через Средиземье. Первая часть трилогии по роману Толкина поразила масштабом съёмок в Новой Зеландии и вниманием к деталям.","fact":"Съёмки всех трёх фильмов трилогии проходили практически одновременно на протяжении более года.","wiki_en":"The Lord of the Rings: The Fellowship of the Ring"},{"name":"Гарри Поттер и философский камень","emoji":"⚡","meta":["фэнтези","2001","Крис Коламбус"],"description":"Мальчик-сирота узнаёт, что он волшебник, и отправляется учиться в школу магии Хогвартс, где заводит друзей и раскрывает семейную тайну. Первый фильм франшизы по книгам Джоан Роулинг положил начало одной из самых кассовых киносерий в истории.","fact":"На роли трёх главных героев создатели просмотрели тысячи детей по всей Великобритании.","wiki_en":"Harry Potter and the Philosopher's Stone (film)"},{"name":"Звёздные войны. Эпизод IV: Новая надежда","emoji":"⚔️","meta":["фантастика","1977","Джордж Лукас"],"description":"Молодой фермер с пустынной планеты оказывается втянут в войну повстанцев против галактической Империи и узнаёт о своём предназначении. Фильм Джорджа Лукаса произвёл революцию в визуальных эффектах и звуке и породил одну из крупнейших франшиз в истории кино.","fact":"Перед премьерой в успех фильма почти никто не верил, а прокатчики выпускали его ограниченным числом копий.","wiki_en":"Star Wars (film)"},{"name":"Титаник","emoji":"🚢","meta":["мелодрама","1997","Джеймс Кэмерон"],"description":"На борту роскошного и, как считалось, непотопляемого лайнера вспыхивает любовь между бедным художником и девушкой из высшего общества, а корабль тем временем идёт навстречу катастрофе. Фильм долгое время оставался самым кассовым в истории.","fact":"Песня My Heart Will Go On в исполнении Селин Дион стала одной из самых узнаваемых кинобаллад в истории.","wiki_en":"Titanic (1997 film)"},{"name":"Аватар","emoji":"🌿","meta":["фантастика","2009","Джеймс Кэмерон"],"description":"Бывший морпех управляет искусственным телом гуманоида-на'ви, чтобы разведать ресурсы на планете Пандора, но постепенно проникается культурой её жителей. Фильм произвёл впечатление масштабным применением 3D и технологии захвата движения, создав целый инопланетный мир.","fact":"Фильм стал самым кассовым в мировом прокате и удерживал этот рекорд много лет.","wiki_en":"Avatar (2009 film)"},{"name":"Парк юрского периода","emoji":"🦖","meta":["фантастика","1993","Стивен Спилберг"],"description":"На уединённом острове учёные с помощью древней ДНК воссоздают динозавров для парка развлечений, но система безопасности выходит из строя, и гости оказываются один на один с хищниками. Фильм Спилберга совершил прорыв в компьютерной графике.","fact":"Часть динозавров в фильме — это аниматронные модели в натуральную величину, а не только компьютерная графика.","wiki_en":"Jurassic Park (film)"},{"name":"Челюсти","emoji":"🦈","meta":["триллер","1975","Стивен Спилберг"],"description":"Небольшой курортный городок оказывается терроризирован гигантской белой акулой, и шериф вместе с океанологом и охотником отправляется в море, чтобы её остановить. Фильм Спилберга считается первым по-настоящему летним блокбастером.","fact":"Механическая акула на площадке постоянно ломалась, из-за чего Спилбергу пришлось дольше держать хищника за кадром — и это усилило напряжение.","wiki_en":"Jaws (film)"},{"name":"Инопланетянин","emoji":"🛸","meta":["фантастика","1982","Стивен Спилберг"],"description":"Мальчик находит в саду забытого на Земле инопланетянина и, прячась от взрослых, помогает ему связаться с домом и вернуться на корабль. Тёплая семейная история Спилберга о дружбе и взрослении стала одним из самых любимых фильмов о пришельцах.","fact":"Сцена полёта на велосипеде на фоне луны стала одним из самых узнаваемых кадров в истории кино.","wiki_en":"E.T. the Extra-Terrestrial"},{"name":"Индиана Джонс: В поисках утраченного ковчега","emoji":"🤠","meta":["приключения","1981","Стивен Спилберг"],"description":"Археолог и авантюрист по прозвищу Индиана Джонс соревнуется с нацистами в поисках библейского Ковчега Завета, обладающего сверхъестественной силой. Фильм соединил дух приключенческих сериалов прошлого с современными на тот момент трюками и погонями.","fact":"Знаменитую сцену с фехтованием против мечника создатели придумали экспромтом, потому что исполнитель главной роли неважно себя чувствовал.","wiki_en":"Raiders of the Lost Ark"},{"name":"Назад в будущее","emoji":"🚗","meta":["фантастика","1985","Роберт Земекис"],"description":"Подросток на переделанном в машину времени автомобиле случайно попадает из 1985 года в 1955-й, где встречает своих будущих родителей молодыми и рискует помешать собственному рождению. Фильм стал классикой жанра путешествий во времени.","fact":"Машиной времени в фильме стал серийный автомобиль DeLorean с характерными дверями, поднимающимися вверх.","wiki_en":"Back to the Future"},{"name":"Терминатор 2: Судный день","emoji":"🤖","meta":["фантастика","1991","Джеймс Кэмерон"],"description":"Робот-терминатор прежней модели теперь защищает мальчика-подростка от нового, более совершенного киборга из жидкого металла, присланного изменить будущее. Сиквел прославился прорывными на тот момент спецэффектами трансформации жидкого металла.","fact":"Фраза I'll be back из первого фильма стала фирменной для героя Арнольда Шварценеггера на десятилетия вперёд.","wiki_en":"Terminator 2: Judgment Day"},{"name":"Чужой","emoji":"👽","meta":["ужасы","1979","Ридли Скотт"],"description":"Экипаж грузового космического корабля откликается на сигнал бедствия с неизвестной планеты и невольно приносит на борт смертоносного инопланетного хищника. Фильм Ридли Скотта соединил космическую фантастику с эстетикой хоррора.","fact":"Дизайн ксеноморфа создал швейцарский художник Ханс Гигер, известный своим мрачным биомеханическим стилем.","wiki_en":"Alien (film)"},{"name":"Бегущий по лезвию","emoji":"🌃","meta":["фантастика","1982","Ридли Скотт"],"description":"В мрачном будущем детектив охотится на беглых биоинженерных репликантов, почти неотличимых от людей, и постепенно задумывается о природе собственного сознания. Экранизация романа Филипа Дика задала визуальный канон киберпанка на десятилетия вперёд.","fact":"При выходе в прокат фильм провалился в кассах и лишь позже был переоценён как один из главных фантастических фильмов XX века.","wiki_en":"Blade Runner"},{"name":"Крепкий орешек","emoji":"🏢","meta":["боевик","1988","Джон Мактирнан"],"description":"Нью-йоркский полицейский в одиночку противостоит банде вооружённых преступников, захвативших небоскрёб на рождественской вечеринке, где находится его жена. Фильм задал канон боевиков «один герой против группы врагов в замкнутом пространстве» на годы вперёд.","fact":"Фраза Yippee-ki-yay героя Брюса Уиллиса стала одной из самых узнаваемых в жанре боевиков.","wiki_en":"Die Hard"},{"name":"Один дома","emoji":"🎄","meta":["комедия","1990","Крис Коламбус"],"description":"Восьмилетнего мальчика по ошибке забывают дома, когда семья улетает на Рождество в Европу, и ему приходится в одиночку защищать дом от двух незадачливых грабителей. Семейная комедия с изобретательными ловушками стала одним из самых узнаваемых рождественских фильмов.","fact":"Больше двух десятилетий фильм оставался самой кассовой комедией с живыми актёрами в мировом прокате.","wiki_en":"Home Alone"},{"name":"Красотка","emoji":"👠","meta":["романтическая комедия","1990","Гарри Маршалл"],"description":"Богатый бизнесмен нанимает девушку с улицы в компаньонки на неделю деловых встреч, и между ними неожиданно вспыхивает настоящее чувство. Современная версия сюжета о Золушке сделала звездой Джулию Робертс и стала одной из самых кассовых романтических комедий.","fact":"Изначально сценарий был мрачной драмой о жизни на улице и лишь после переработки студией превратился в романтическую комедию со счастливым финалом.","wiki_en":"Pretty Woman"},{"name":"Грязные танцы","emoji":"💃","meta":["музыкальная мелодрама","1987","Эмиль Ардолино"],"description":"На летнем курорте девушка из благополучной семьи влюбляется в танцора из бедной среды и тайком готовится вместе с ним к ответственному выступлению. Фильм прославился танцевальными номерами и саундтреком, включая знаменитую песню (I've Had) The Time of My Life.","fact":"Финальный подъём партнёрши над головой стал одним из самых пародируемых танцевальных движений в кино.","wiki_en":"Dirty Dancing"},{"name":"Привидение","emoji":"👻","meta":["мелодрама","1990","Джерри Цукер"],"description":"Убитый мужчина остаётся на земле призраком и с помощью мошенницы-медиума пытается защитить свою возлюбленную и раскрыть обстоятельства собственной смерти. Фильм соединил мистику с трогательной любовной драмой и подарил кино одну из самых цитируемых сцен с гончарным кругом.","fact":"Песня Unchained Melody, звучащая в знаменитой сцене с глиной, снова стала хитом спустя четверть века после оригинальной записи The Righteous Brothers.","wiki_en":"Ghost (1990 film)"},{"name":"Молчание ягнят","emoji":"🦋","meta":["триллер","1991","Джонатан Демме"],"description":"Молодая слушательница академии ФБР консультируется с заключённым психиатром-каннибалом Ганнибалом Лектером, чтобы выйти на след другого серийного убийцы. Фильм стал одним из немногих триллеров, получивших «Оскар» за лучший фильм.","fact":"Энтони Хопкинс провёл в кадре в роли Лектера чуть более пятнадцати минут, но этого хватило, чтобы получить «Оскар» за главную роль.","wiki_en":"The Silence of the Lambs (film)"},{"name":"Семь","emoji":"📦","meta":["триллер","1995","Дэвид Финчер"],"description":"Два детектива, один на пороге отставки, другой только начинающий службу, расследуют серию убийств, в которых преступник вдохновляется семью смертными грехами. Мрачная атмосфера постоянного дождя и жёсткая режиссура Финчера сделали фильм эталоном криминального триллера 1990-х.","fact":"Финал фильма с коробкой стал одним из самых обсуждаемых и пародируемых поворотов в истории триллеров.","wiki_en":"Seven (1995 film)"},{"name":"Зелёная миля","emoji":"🐭","meta":["драма","1999","Фрэнк Дарабонт"],"description":"Надзиратель блока смертников в тюрьме 1930-х годов сталкивается с осуждённым великаном, обладающим необъяснимым даром исцеления. Экранизация романа Стивена Кинга сочетает тюремную драму с элементами мистики и размышлениями о вере и справедливости.","fact":"Роман Стивена Кинга, положенный в основу фильма, изначально выходил отдельными выпусками, как сериал в мягкой обложке.","wiki_en":"The Green Mile (film)"},{"name":"Список Шиндлера","emoji":"🕯️","meta":["историческая драма","1993","Стивен Спилберг"],"description":"Немецкий предприниматель Оскар Шиндлер во время Второй мировой войны спасает жизни более тысячи польских евреев, нанимая их на работу на свою фабрику. Снятый почти полностью в чёрно-белой гамме фильм Спилберга основан на реальной истории.","fact":"Спилберг отказался от гонорара за этот фильм, а на доходы от него основал фонд, записывающий свидетельства переживших Холокост.","wiki_en":"Schindler's List"},{"name":"Спасти рядового Райана","emoji":"🪖","meta":["военная драма","1998","Стивен Спилберг"],"description":"Отряд американских солдат получает приказ найти и вернуть домой единственного выжившего из четырёх братьев после высадки в Нормандии. Открывающая фильм долгая сцена штурма пляжа считается одной из самых реалистичных батальных сцен в истории кино.","fact":"Из-за предельно жёсткого изображения боя некоторые ветераны Второй мировой войны, по свидетельствам, покидали кинозал во время просмотра.","wiki_en":"Saving Private Ryan"},{"name":"Гладиатор","emoji":"⚔️","meta":["историческая драма","2000","Ридли Скотт"],"description":"Римский полководец, преданный завистливым наследником императора, лишается семьи и свободы и оказывается на арене гладиатором, вынашивая план мести. Фильм Ридли Скотта возродил интерес к жанру пеплума и античным сюжетам в голливудском кино.","fact":"Фраза героя «Меня зовут Максимус Децим Меридий» стала одной из самых узнаваемых реплик-представлений в кино.","wiki_en":"Gladiator (2000 film)"},{"name":"Храброе сердце","emoji":"🗡️","meta":["историческая драма","1995","Мел Гибсон"],"description":"Шотландец Уильям Уоллес поднимает восстание против английского владычества после того, как английские солдаты убивают его жену. Масштабная историческая драма с батальными сценами принесла Мелу Гибсону «Оскар» за режиссуру.","fact":"Клетчатый рисунок килтов в фильме исторически не соответствует эпохе — тартаны в таком виде появились значительно позже показанных событий.","wiki_en":"Braveheart"},{"name":"Леон","emoji":"🌱","meta":["криминальная драма","1994","Люк Бессон"],"description":"Профессиональный убийца-одиночка берёт под опеку двенадцатилетнюю девочку, чью семью убили коррумпированные агенты, и невольно привязывается к ней. Фильм Люка Бессона сочетает жёсткий боевик с неожиданно трогательной историей о дружбе и защите.","fact":"Комнатное растение, которое герой всюду носит с собой и о котором заботится как о единственном друге, стало символом всего фильма.","wiki_en":"Léon: The Professional"},{"name":"Пятый элемент","emoji":"🚕","meta":["фантастика","1997","Люк Бессон"],"description":"Таксист в футуристическом Нью-Йорке XXIII века неожиданно оказывается втянут в спасение мира вместе с загадочной девушкой, воплощающей древнее оружие против абсолютного зла. Яркий визуальный стиль Люка Бессона соединил комикс-эстетику с масштабной космической фантастикой.","fact":"Костюмы для фильма разработал модельер Жан-Поль Готье, включая знаменитый наряд из бинтов у героини Милы Йовович.","wiki_en":"The Fifth Element"},{"name":"Король Лев","emoji":"🦁","meta":["мультфильм","1994","Роджер Аллерс, Роб Минкофф"],"description":"Львёнок Симба должен унаследовать трон отца в африканской саванне, но после трагедии, в которой винит себя, бежит из родного прайда и годы спустя возвращается, чтобы занять законное место. Мультфильм Disney с музыкой Элтона Джона стал одним из самых кассовых анимационных фильмов своего времени.","fact":"Сюжет мультфильма во многом перекликается с шекспировским «Гамлетом» — с мотивами предательства и мести за отца.","wiki_en":"The Lion King"},{"name":"История игрушек","emoji":"🧸","meta":["мультфильм","1995","Джон Лассетер"],"description":"Ковбой Вуди, любимая игрушка мальчика Энди, ревниво воспринимает появление нового яркого космического рейнджера Базза Лайтера и постепенно учится делить внимание хозяина. Фильм студии Pixar стал первым полнометражным мультфильмом, полностью созданным на компьютере.","fact":"Рендер отдельных кадров первого полностью компьютерного мультфильма занимал часы на тогдашних компьютерах.","wiki_en":"Toy Story"},{"name":"Шрек","emoji":"🧅","meta":["мультфильм","2001","Эндрю Адамсон, Вики Дженсон"],"description":"Угрюмый зелёный людоед, желающий вернуть уединение на своём болоте, соглашается спасти принцессу из башни, охраняемой драконом, в обмен на возвращение земель. Мультфильм пародирует классические сказочные сюжеты и сочетает добрый юмор с ироничными отсылками для взрослых.","fact":"Фраза Шрека о том, что у людоедов, как у луковиц, есть слои, стала одной из самых цитируемых в мультфильме.","wiki_en":"Shrek"},{"name":"В поисках Немо","emoji":"🐠","meta":["мультфильм","2003","Эндрю Стэнтон"],"description":"Рыба-клоун по имени Марлин отправляется через весь океан на поиски похищенного аквариумистами сына Немо, преодолевая опасности вместе с рассеянной, но доброй спутницей Дори. Мультфильм Pixar прославился реалистичной анимацией подводного мира.","fact":"После выхода мультфильма резко вырос спрос на рыб-клоунов для домашних аквариумов, что обеспокоило защитников природы.","wiki_en":"Finding Nemo"},{"name":"ВАЛЛ-И","emoji":"🤖","meta":["мультфильм","2008","Эндрю Стэнтон"],"description":"На опустевшей от мусора Земле остаётся работать одинокий робот-уборщик, который влюбляется в прилетевшего с разведывательной миссией робота нового поколения. Первая треть мультфильма почти лишена диалогов, но полна выразительной пантомимы.","fact":"Голос и звуки ВАЛЛ-И придумал звукорежиссёр Бен Бёртт — тот же человек, что когда-то создал «речь» робота R2-D2.","wiki_en":"WALL-E"},{"name":"Вверх","emoji":"🎈","meta":["мультфильм","2009","Пит Доктер"],"description":"Пожилой вдовец прикрепляет к своему дому тысячи воздушных шаров и отправляется в путешествие в Южную Америку, о котором мечтал с женой, а по пути обнаруживает на борту юного бойскаута. Мультфильм Pixar известен пронзительным вступлением о целой совместной жизни без единого слова.","fact":"Помимо награды за анимацию, мультфильм получил редкую для жанра номинацию на «Оскар» за лучший фильм года.","wiki_en":"Up (2009 film)"},{"name":"Холодное сердце","emoji":"❄️","meta":["мультфильм","2013","Крис Бак, Дженнифер Ли"],"description":"Принцесса с даром замораживать всё вокруг случайно погружает родное королевство в вечную зиму и скрывается в горах, а её сестра отправляется на поиски, чтобы всё исправить. Мультфильм Disney сделал главной темой не романтическую любовь, а связь между сёстрами.","fact":"Песня Let It Go из мультфильма стала мировым хитом и была записана на десятках языков.","wiki_en":"Frozen (2013 film)"},{"name":"Унесённые призраками","emoji":"🐉","meta":["мультфильм","2001","Хаяо Миядзаки"],"description":"Девочка по дороге на новое место жительства с родителями попадает в мир духов, где её родителей превращают в свиней, и ей приходится устроиться на работу в волшебные бани, чтобы спасти семью. Мультфильм Хаяо Миядзаки стал первым аниме, получившим «Оскар».","fact":"Фильм долгое время оставался самым кассовым в истории японского кинопроката.","wiki_en":"Spirited Away"},{"name":"Пираты Карибского моря: Проклятие Чёрной жемчужины","emoji":"🏴‍☠️","meta":["приключения","2003","Гор Вербински"],"description":"Кузнец отправляется спасать похищенную дочь губернатора вместе с эксцентричным пиратом Джеком Воробьём, чей корабль проклят, а команда обращается в скелетов при лунном свете. Фильм по мотивам аттракциона Disneyland неожиданно возродил жанр пиратских приключений.","fact":"Роль Джека Воробья Джонни Депп во многом построил на манерах музыканта Кита Ричардса.","wiki_en":"Pirates of the Caribbean: The Curse of the Black Pearl"},{"name":"Человек-паук","emoji":"🕷️","meta":["супергеройский фильм","2002","Сэм Рэйми"],"description":"Обычный школьник Питер Паркер после укуса радиоактивного паука обретает сверхспособности и, после гибели дяди, решает использовать их во благо города. Фильм Сэма Рэйми стал одним из первых по-настоящему кассовых супергеройских блокбастеров XXI века.","fact":"Фраза дяди Бена «с большой силой приходит и большая ответственность» стала девизом персонажа на десятилетия вперёд.","wiki_en":"Spider-Man (2002 film)"},{"name":"Железный человек","emoji":"🦾","meta":["супергеройский фильм","2008","Джон Фавро"],"description":"Миллиардер и оружейный магнат, попавший в плен, строит бронированный костюм, чтобы выбраться, а вернувшись домой, продолжает совершенствовать его для борьбы со злом. Фильм положил начало кинематографической вселенной Marvel.","fact":"Сцена после титров с появлением Ника Фьюри задала традицию пост-титровых эпизодов, связывающих фильмы Marvel в одну вселенную.","wiki_en":"Iron Man (2008 film)"},{"name":"Мстители","emoji":"🛡️","meta":["супергеройский фильм","2012","Джосс Уидон"],"description":"Отряд самых сильных героев Земли — Железный человек, Тор, Капитан Америка, Халк и другие — впервые объединяется, чтобы остановить вторжение инопланетной армии на Нью-Йорк. Фильм стал первым масштабным кроссовером кинематографической вселенной Marvel.","fact":"Собрать всех героев из отдельных франшиз в одном фильме до этого в таком масштабе в кино почти не пробовали.","wiki_en":"The Avengers (2012 film)"},{"name":"Мстители: Финал","emoji":"💎","meta":["супергеройский фильм","2019","Энтони Руссо, Джо Руссо"],"description":"После катастрофических событий предыдущего фильма оставшиеся супергерои ищут способ обратить вспять уничтожение половины всего живого во вселенной. Финал многолетней саги Marvel стал одним из самых кассовых фильмов в истории кино.","fact":"Фильм на некоторое время стал самым кассовым в мировой истории кинопроката, обойдя «Аватар».","wiki_en":"Avengers: Endgame"},{"name":"Джокер","emoji":"🃏","meta":["драма","2019","Тодд Филлипс"],"description":"Неудачливый клоун и начинающий комик, страдающий психическим расстройством, постепенно теряет связь с реальностью на фоне равнодушия и жестокости окружающего его Готэма. Фильм переосмыслил происхождение классического злодея как мрачную социальную драму.","fact":"Хоакин Феникс сбросил значительный вес ради роли, чтобы придать герою измождённый, надломленный вид.","wiki_en":"Joker (2019 film)"},{"name":"Дэдпул","emoji":"🗡️","meta":["супергеройская комедия","2016","Тим Миллер"],"description":"Бывший спецназовец, ставший подопытным в подпольном эксперименте по исцелению от рака, обретает сверхспособности вместе с обезображенной внешностью и мстит под маской болтливого наёмника. Фильм выделяется ломанием четвёртой стены и чёрным юмором, нетипичным для жанра.","fact":"Райан Рейнольдс годами добивался съёмок фильма, и решающую роль сыграл утёкший в сеть тестовый ролик, который восторженно приняли зрители.","wiki_en":"Deadpool (film)"},{"name":"Стражи Галактики","emoji":"🌌","meta":["супергеройский фильм","2014","Джеймс Ганн"],"description":"Разношёрстная банда космических изгоев — включая говорящего енота и человекоподобное дерево — случайно оказывается втянута в схватку за могущественный артефакт, способный уничтожить целые планеты. Фильм выделялся ретро-саундтреком из хитов 1970-х.","fact":"Плейлист Awesome Mix с ретро-хитами, который слушает главный герой, стал самостоятельным хитом на музыкальных сервисах.","wiki_en":"Guardians of the Galaxy (film)"},{"name":"Безумный Макс: Дорога ярости","emoji":"🏜️","meta":["боевик","2015","Джордж Миллер"],"description":"В выжженной пустоши постапокалиптического будущего беглянка-военачальница Фуриоса вместе со случайным попутчиком Максом пытается вырваться от тирана-деспота на гружённом женщинами грузовике. Почти двухчасовая автомобильная погоня принесла фильму широкое признание критиков.","fact":"Большинство трюков и автомобильных каскадов в фильме сняты практически без компьютерной графики.","wiki_en":"Mad Max: Fury Road"},{"name":"Джон Уик","emoji":"🐶","meta":["боевик","2014","Чад Стахелски"],"description":"Отошедший от дел наёмный убийца возвращается к прежнему ремеслу после того, как бывшие сообщники убивают подаренного покойной женой щенка и угоняют его машину. Фильм известен изобретательной хореографией перестрелок и рукопашного боя, задавшей новый стандарт жанра.","fact":"Постановкой боевых сцен занимались бывшие каскадёры, что придало перестрелкам необычную для Голливуда физическую достоверность.","wiki_en":"John Wick (film)"},{"name":"Убить Билла","emoji":"🟡","meta":["боевик","2003","Квентин Тарантино"],"description":"Бывшая наёмная убийца, выжившая после расстрела на собственной свадьбе, составляет список бывших коллег из «Смертельной гадюки» и мстит им одному за другим. Фильм Тарантино соединяет эстетику японских самурайских лент, гонконгских боевиков и спагетти-вестернов.","fact":"Жёлтый спортивный костюм героини — прямая отсылка к экипировке Брюса Ли в фильме «Игра смерти».","wiki_en":"Kill Bill: Volume 1"},{"name":"Джанго освобождённый","emoji":"⛓️","meta":["вестерн","2012","Квентин Тарантино"],"description":"Освобождённый раб объединяется с немецким охотником за головами, чтобы найти и спасти жену, оставшуюся в рабстве у жестокого плантатора на юге США. Тарантино переосмысляет жанр спагетти-вестерна через призму темы рабства в довоенной Америке.","fact":"Название и часть музыкальной темы фильма отсылают к итальянскому вестерну 1966 года «Джанго».","wiki_en":"Django Unchained"},{"name":"Бесславные ублюдки","emoji":"🎬","meta":["военная драма","2009","Квентин Тарантино"],"description":"Отряд американских солдат-евреев охотится за нацистскими офицерами во Франции времён Второй мировой войны, а параллельно хозяйка парижского кинотеатра готовит собственную месть за убитую семью. Тарантино соединяет альтернативную историю с данью уважения кино.","fact":"Название фильма содержит намеренную орфографическую ошибку, оставленную без объяснений.","wiki_en":"Inglourious Basterds"},{"name":"Однажды в… Голливуде","emoji":"📺","meta":["трагикомедия","2019","Квентин Тарантино"],"description":"Стареющий актёр телевизионных вестернов и его каскадёр-дублёр пытаются удержаться на плаву в стремительно меняющемся Голливуде конца 1960-х, по соседству с домом Шэрон Тейт. Фильм Тарантино воссоздаёт атмосферу Лос-Анджелеса той эпохи.","fact":"Действие фильма разворачивается в Лос-Анджелесе 1969 года и отсылает к реальным трагическим событиям того времени.","wiki_en":"Once Upon a Time in Hollywood"},{"name":"Волк с Уолл-стрит","emoji":"💰","meta":["биографическая комедия","2013","Мартин Скорсезе"],"description":"Биржевой брокер Джордан Белфорт строит финансовую империю на мошеннических схемах и стремительно скатывается в мир немыслимой роскоши, наркотиков и вседозволенности. Фильм основан на реальных мемуарах и известен энергичным темпом и провокационным юмором.","fact":"Леонардо Ди Каприо сыграл в фильме реального человека, Джордана Белфорта, который позже появляется в эпизодической роли в самой картине.","wiki_en":"The Wolf of Wall Street (2013 film)"},{"name":"Остров проклятых","emoji":"🏝️","meta":["психологический триллер","2010","Мартин Скорсезе"],"description":"Федеральный маршал расследует таинственное исчезновение пациентки из психиатрической лечебницы на удалённом острове, но чем дальше продвигается расследование, тем менее надёжной кажется реальность вокруг него. Экранизация романа Денниса Лихейна выстроена как атмосферный триллер.","fact":"Мартин Скорсезе намеренно насыщал фильм визуальными и сюжетными подсказками, которые становятся понятны только при повторном просмотре.","wiki_en":"Shutter Island (film)"},{"name":"Отступники","emoji":"🕵️","meta":["криминальная драма","2006","Мартин Скорсезе"],"description":"Полицейский под прикрытием внедряется в ирландскую мафию Бостона, в то время как человек мафии одновременно работает кротом внутри самой полиции, и оба пытаются вычислить друг друга. Фильм принёс Мартину Скорсезе первый в карьере «Оскар» за режиссуру.","fact":"Сюжет фильма — ремейк гонконгского триллера «Двойная рокировка».","wiki_en":"The Departed"},{"name":"Славные парни","emoji":"🔫","meta":["криминальная драма","1990","Мартин Скорсезе"],"description":"История восхождения и падения мелкого гангстера, который с юности мечтал стать частью итало-американской мафии Нью-Йорка и постепенно проходит путь от мелких краж до крупных преступлений. Фильм основан на реальной биографии и известен стремительным монтажом.","fact":"Знаменитый длинный непрерывный кадр прохода через кухню ресторана в фильме снят одним дублем без видимых склеек.","wiki_en":"Goodfellas"},{"name":"Таксист","emoji":"🚕","meta":["психологическая драма","1976","Мартин Скорсезе"],"description":"Одинокий ветеран войны во Вьетнаме подрабатывает ночным таксистом в криминальном Нью-Йорке и, всё больше отчуждаясь от общества, вынашивает план насильственного очищения города. Фильм стал одним из главных портретов городского одиночества в американском кино.","fact":"Музыку к фильму написал Бернард Херрманн, многолетний соавтор Хичкока, — это была его последняя работа в кино, и картина посвящена его памяти.","wiki_en":"Taxi Driver"},{"name":"Лицо со шрамом","emoji":"🌎","meta":["криминальная драма","1983","Брайан Де Пальма"],"description":"Кубинский эмигрант Тони Монтана прибывает в Майами без денег и постепенно выстраивает наркоимперию, поднимаясь по кровавой лестнице криминального мира. Ремейк фильма 1932 года стал культовой историей об американской мечте, вывернутой наизнанку.","fact":"Надпись «Мир принадлежит тебе», которую герой видит в небе на пролетающем дирижабле, стала девизом всей истории.","wiki_en":"Scarface (1983 film)"},{"name":"Большой Лебовски","emoji":"🎳","meta":["комедия","1998","Итан Коэн, Джоэл Коэн"],"description":"Ленивого любителя боулинга по прозвищу Чувак по ошибке принимают за миллионера с тем же именем, втягивая в нелепую историю с похищением и выкупом. Эксцентричная комедия братьев Коэн поначалу прошла незамеченной, но со временем обрела огромный культовый фандом.","fact":"Поклонники фильма ежегодно устраивают посвящённые ему фестивали Lebowski Fest с боулингом и костюмами героев.","wiki_en":"The Big Lebowski"},{"name":"Старикам тут не место","emoji":"🪙","meta":["триллер","2007","Итан Коэн, Джоэл Коэн"],"description":"Случайно наткнувшийся на деньги с места неудавшейся наркосделки охотник пытается скрыться от безжалостного убийцы, преследующего его по пустошам Техаса. Экранизация романа Кормака Маккарти принесла братьям Коэн «Оскар» за лучший фильм.","fact":"Главное оружие убийцы в фильме — пневматический пистолет для забоя скота, совершенно необычный выбор для криминального триллера.","wiki_en":"No Country for Old Men"},{"name":"Красота по-американски","emoji":"🌹","meta":["драма","1999","Сэм Мендес"],"description":"Разочарованный в жизни и браке мужчина среднего возраста переживает кризис, влюбляется в подругу дочери и решает радикально изменить свою жизнь наперекор пригородным условностям. Фильм известен визуальной символикой, в частности образом рассыпанных лепестков роз.","fact":"Летящий по ветру полиэтиленовый пакет в одной из сцен стал одним из самых обсуждаемых и пародируемых символов фильма.","wiki_en":"American Beauty (1999 film)"},{"name":"Шестое чувство","emoji":"👦","meta":["мистический триллер","1999","М. Найт Шьямалан"],"description":"Детский психолог пытается помочь мальчику, который утверждает, что видит мёртвых людей, и постепенно оба сталкиваются с истиной, меняющей всё понимание истории. Фильм прославился одним из самых неожиданных финальных твистов в истории кино.","fact":"Фраза мальчика «Я вижу мёртвых людей» стала одной из самых узнаваемых и часто пародируемых реплик в кино.","wiki_en":"The Sixth Sense"},{"name":"Игры разума","emoji":"🧮","meta":["биографическая драма","2001","Рон Ховард"],"description":"Талантливый математик Джон Нэш добивается прорывных научных результатов, одновременно борясь с прогрессирующей шизофренией, которая искажает его восприятие реальности. Фильм основан на биографии реального нобелевского лауреата по экономике.","fact":"Картина получила «Оскар» за лучший фильм года, а Дженнифер Коннелли — за лучшую женскую роль второго плана.","wiki_en":"A Beautiful Mind (film)"},{"name":"Поймай меня, если сможешь","emoji":"✈️","meta":["криминальная комедия","2002","Стивен Спилберг"],"description":"Подросток становится виртуозным мошенником, выдающим себя за пилота, врача и юриста и подделывающим чеки на миллионы долларов, пока за ним не начинает охоту упорный агент ФБР. Фильм основан на автобиографии реального афериста Фрэнка Абигнейла.","fact":"Реальный Фрэнк Абигнейл, чья история легла в основу сюжета, позже стал консультантом по банковской безопасности.","wiki_en":"Catch Me If You Can"},{"name":"Одиннадцать друзей Оушена","emoji":"🎰","meta":["криминальная комедия","2001","Стивен Содерберг"],"description":"Профессиональный аферист Дэнни Оушен собирает команду из одиннадцати специалистов, чтобы провернуть дерзкое ограбление сразу трёх казино Лас-Вегаса в одну ночь. Ремейк фильма 1960 года со звёздным составом стал эталоном лёгкого стильного кино об ограблениях.","fact":"Сцена с фонтанами отеля Bellagio, на фоне которых молча стоят герои в финале, стала одним из самых узнаваемых кадров фильма.","wiki_en":"Ocean's Eleven (2001 film)"},{"name":"Миссия невыполнима","emoji":"🕶️","meta":["боевик","1996","Брайан Де Пальма"],"description":"Агента спецслужбы подставляют после провала миссии, в результате которой погибает вся его команда, и он вынужден в одиночку выяснять, кто предатель, оставаясь вне закона. Фильм по мотивам культового телесериала 1960-х положил начало долгоживущей экшен-франшизе Тома Круза.","fact":"Сцена проникновения в защищённое хранилище ЦРУ, где герой спускается на тросе почти касаясь пола, стала одной из самых пародируемых в кино.","wiki_en":"Mission: Impossible (film)"},{"name":"Казино «Рояль»","emoji":"🎲","meta":["шпионский боевик","2006","Мартин Кэмпбелл"],"description":"Новичок в статусе агента 007 Джеймс Бонд получает первое серьёзное задание — обыграть в покер финансиста террористов за карточным столом в казино в Черногории. Фильм перезапустил франшизу о Бонде с более жёстким и приземлённым тоном.","fact":"Это был первый фильм о Бонде с Дэниэлом Крейгом, который поначалу вызвал скепсис у части фанатов, но позже завоевал признание.","wiki_en":"Casino Royale (2006 film)"},{"name":"Рокки","emoji":"🥊","meta":["спортивная драма","1976","Джон Эвилдсен"],"description":"Малоизвестный боксёр из рабочего района Филадельфии неожиданно получает шанс сразиться с чемпионом мира в титульном бою и использует его, чтобы доказать себе и другим, что способен пройти дистанцию. Малобюджетный фильм со Сталлоне стал одной из главных историй об упорстве в кино.","fact":"Пробежка героя по ступеням Филадельфийского художественного музея превратилась в туристическую достопримечательность, известную как «ступени Рокки».","wiki_en":"Rocky"},{"name":"Рэмбо: Первая кровь","emoji":"🔪","meta":["боевик","1982","Тед Котчефф"],"description":"Ветеран войны во Вьетнаме, столкнувшись с несправедливым преследованием со стороны полиции маленького городка, скрывается в лесу и в одиночку противостоит целому отряду. Фильм поднимает тему непростого возвращения ветеранов к мирной жизни и представляет публике героя Рэмбо.","fact":"В отличие от кровопролитных сиквелов, в первом фильме герой почти не убивает — он в основном обезвреживает и запугивает преследователей.","wiki_en":"First Blood"},{"name":"Хищник","emoji":"👽","meta":["фантастический боевик","1987","Джон Мактирнан"],"description":"Отряд элитных спецназовцев отправляется на спасательную операцию в центральноамериканские джунгли и один за другим становится добычей невидимого инопланетного охотника. Фильм соединил военный боевик с фантастикой ужасов и подарил жанру одного из самых узнаваемых монстров.","fact":"Костюм Хищника изначально создавался для другого актёра и облика, но был полностью переделан незадолго до съёмок по настоянию создателей.","wiki_en":"Predator (film)"},{"name":"Робокоп","emoji":"🦾","meta":["фантастический боевик","1987","Пол Верховен"],"description":"Тяжело раненный при исполнении полицейский Детройта возвращается на службу в виде киборга с почти утраченной человеческой памятью и постепенно вспоминает, кем он был. Фильм Пола Верховена соединяет жёсткий боевик с острой сатирой на корпорации и медиа.","fact":"Из-за чрезмерной жестокости фильм пришлось несколько раз перемонтировать, чтобы получить в США прокатный рейтинг вместо запретительного.","wiki_en":"RoboCop"},{"name":"Охотники за привидениями","emoji":"👻","meta":["фантастическая комедия","1984","Айван Райтман"],"description":"Трое незадачливых учёных-парапсихологов открывают в Нью-Йорке частную службу по отлову призраков и неожиданно сталкиваются с настоящим сверхъестественным нашествием. Фильм соединил комедию с фантастикой о привидениях и стал культовой классикой 1980-х.","fact":"Песня Ghostbusters Рэя Паркера-младшего из этого фильма поднялась на первое место американского чарта синглов.","wiki_en":"Ghostbusters (1984 film)"},{"name":"Люди в чёрном","emoji":"🕶️","meta":["фантастическая комедия","1997","Барри Зонненфельд"],"description":"Секретное агентство в строгих чёрных костюмах тайно следит за инопланетянами, живущими среди людей на Земле, и новобранец вместе с опытным напарником берётся за расследование опасного дела. Фильм по мотивам комикса сочетает экшен, юмор и изобретательный дизайн пришельцев.","fact":"Устройство-вспышка, стирающее память свидетелям в фильме, стало одним из узнаваемых атрибутов поп-культуры — нейрализатор.","wiki_en":"Men in Black (1997 film)"},{"name":"День сурка","emoji":"🔁","meta":["комедия","1993","Гарольд Рэмис"],"description":"Циничный телеведущий-метеоролог застревает во временной петле и снова и снова проживает один и тот же день в маленьком городке, пока не меняется как личность. Фильм подарил массовой культуре само выражение «день сурка» для обозначения бесконечного повторения.","fact":"Точное число повторяющихся дней в фильме никогда не называется, но по подсчётам поклонников оно могло составлять годы.","wiki_en":"Groundhog Day (film)"},{"name":"Маска","emoji":"🎭","meta":["фантастическая комедия","1994","Чак Расселл"],"description":"Скромный банковский служащий находит древнюю маску, надев которую превращается в безумного зеленолицего персонажа с суперспособностями и раскованным характером. Фильм прославил Джима Керри как звезду эксцентричной физической комедии и активно использовал компьютерную графику для трансформаций героя.","fact":"Комикс, по которому снят фильм, изначально был куда мрачнее и жёстче итоговой комедийной экранизации.","wiki_en":"The Mask (1994 film)"},{"name":"Тупой и ещё тупее","emoji":"🚐","meta":["комедия","1994","Питер Фаррелли"],"description":"Два наивных и недалёких приятеля отправляются через всю страну, чтобы вернуть забытый чемодан с деньгами симпатичной девушке, даже не подозревая, что внутри выкуп для похитителей. Абсурдная комедия с Джимом Керри и Джеффом Дэниелсом стала классикой жанра «глупых» комедий 1990-х.","fact":"Фургон героев, оформленный под лохматую собаку, стал одним из самых узнаваемых автомобилей в истории кинокомедий.","wiki_en":"Dumb and Dumber"},{"name":"Мальчишник в Вегасе","emoji":"🐯","meta":["комедия","2009","Тодд Филлипс"],"description":"Трое друзей просыпаются в номере отеля в Лас-Вегасе после дикой ночи перед свадьбой, не помня ничего из произошедшего, а жених и вовсе бесследно исчез. Комедия строится вокруг попыток героев по обрывочным уликам восстановить события прошлой ночи.","fact":"Фильм стал одной из самых кассовых комедий с рейтингом R за всю историю проката.","wiki_en":"The Hangover"},{"name":"Американский пирог","emoji":"🥧","meta":["подростковая комедия","1999","Пол Уайц"],"description":"Четверо старшеклассников заключают пакт лишиться девственности до выпускного бала и переживают из-за этого серию неловких и комичных ситуаций. Фильм стал одной из самых узнаваемых подростковых комедий рубежа веков и дал начало целой киносерии.","fact":"Снятая с очень скромным бюджетом комедия неожиданно собрала в мировом прокате больше двухсот миллионов долларов.","wiki_en":"American Pie (film)"},{"name":"Дьявол носит Prada","emoji":"👜","meta":["комедийная драма","2006","Дэвид Фрэнкел"],"description":"Выпускница журфака устраивается ассистенткой к деспотичной и требовательной главной редакторше модного журнала и постепенно теряет себя в погоне за успехом в мире высокой моды. Экранизация романа Лорен Вайсбергер во многом основана на реальном опыте работы автора в индустрии моды.","fact":"Прообразом властной героини фильма считается реальная легендарная главред американского Vogue Анна Винтур.","wiki_en":"The Devil Wears Prada (film)"},{"name":"Ла-Ла Ленд","emoji":"🎹","meta":["мюзикл","2016","Дэмьен Шазелл"],"description":"Начинающая актриса и джазовый пианист влюбляются друг в друга в современном Лос-Анджелесе, пытаясь при этом не потерять собственные творческие амбиции. Мюзикл отдаёт дань голливудской классике жанра и известен ярким использованием цвета и танцевальными номерами.","fact":"На церемонии «Оскара» фильм по ошибке на несколько минут объявили победителем в номинации «Лучший фильм» вместо настоящего лауреата.","wiki_en":"La La Land (film)"},{"name":"Одержимость","emoji":"🥁","meta":["драма","2014","Дэмьен Шазелл"],"description":"Амбициозный молодой барабанщик консерватории попадает в класс к жестокому и требовательному дирижёру, готовому унижать студентов ради стремления к музыкальному совершенству. Фильм исследует цену одержимости мастерством и построен на напряжённом противостоянии учителя и ученика.","fact":"За роль деспотичного наставника Дж. К. Симмонс получил «Оскар» за лучшую мужскую роль второго плана.","wiki_en":"Whiplash (2014 film)"},{"name":"Паразиты","emoji":"🪨","meta":["социальный триллер","2019","Пон Джун Хо"],"description":"Бедная семья из полуподвальной квартиры Сеула постепенно и хитроумно внедряется в дом состоятельного семейства, устраиваясь туда на работу под чужими личинами. Южнокорейский фильм соединяет чёрную комедию с острой социальной драмой о неравенстве.","fact":"Фильм стал первым неанглоязычным лауреатом «Оскара» за лучший фильм в истории премии.","wiki_en":"Parasite (2019 film)"},{"name":"Оппенгеймер","emoji":"☢️","meta":["биографическая драма","2023","Кристофер Нолан"],"description":"Физик Роберт Оппенгеймер возглавляет секретный Манхэттенский проект по созданию первой атомной бомбы, а после войны сталкивается с политическими последствиями и моральной тяжестью своего изобретения. Фильм Кристофера Нолана снят в основном на плёнку.","fact":"Взрыв атомной бомбы для сцены испытания «Тринити» был воссоздан практическими эффектами без использования компьютерной графики.","wiki_en":"Oppenheimer (film)"},{"name":"Барби","emoji":"💗","meta":["комедия","2023","Грета Гервиг"],"description":"Классическая кукла Барби из идеального розового мира неожиданно начинает задумываться о смерти и несовершенстве и вместе с Кеном отправляется в реальный мир, чтобы разобраться в себе. Фильм соединяет яркую комедию с ироничным разговором о наследии самой известной куклы в истории.","fact":"Из-за масштабных закупок розовой краски для декораций съёмочная группа якобы временно вызвала её дефицит на рынке.","wiki_en":"Barbie (film)"},{"name":"Дюна","emoji":"🏜️","meta":["фантастика","2021","Дени Вильнёв"],"description":"Наследник благородного дома принимает управление пустынной планетой Арракис, единственным источником ценнейшего во вселенной вещества, и оказывается втянут в смертельные политические интриги. Экранизация романа Фрэнка Герберта известна масштабной постановкой пустынного мира и песчаных червей.","fact":"Роман Фрэнка Герберта, легший в основу фильма, десятилетиями считался «непроходимым» для экранизации из-за сложности мира.","wiki_en":"Dune (2021 film)"},{"name":"Топ Ган: Мэверик","emoji":"✈️","meta":["боевик","2022","Джозеф Косински"],"description":"Ветеран-лётчик Мэверик возвращается инструктором в элитную школу пилотов, чтобы подготовить новое поколение к почти невыполнимой боевой миссии. Спустя десятилетия после оригинала сиквел прославился реальными съёмками воздушных манёвров, а не компьютерной графикой.","fact":"Актёры проходили лётную подготовку и снимались в настоящих реактивных самолётах во время манёвров с реальными перегрузками.","wiki_en":"Top Gun: Maverick"},{"name":"Голодные игры","emoji":"🏹","meta":["фантастический боевик","2012","Гэри Росс"],"description":"В антиутопическом будущем подростков из бедных округов ежегодно отправляют на смертельное телешоу-соревнование, и девушка вызывается добровольцем вместо младшей сестры. Экранизация романа Сьюзен Коллинз стала одной из главных подростковых франшиз своего времени.","fact":"Приветственный жест из трёх пальцев, пришедший из книг, позже стали использовать как символ протеста в разных странах.","wiki_en":"The Hunger Games (film)"},{"name":"Сумерки","emoji":"🧛","meta":["фэнтезийная мелодрама","2008","Кэтрин Хардвик"],"description":"Обычная старшеклассница переезжает в маленький дождливый городок и влюбляется в загадочного одноклассника, который оказывается вампиром, борющимся с собственной природой. Экранизация романа Стефани Майер породила одну из самых заметных подростковых франшиз о вампирах.","fact":"Небольшой городок Форкс в штате Вашингтон, где происходит действие, после выхода фильма превратился в место паломничества поклонников.","wiki_en":"Twilight (2008 film)"},{"name":"1+1","emoji":"🤝","meta":["комедийная драма","2011","Оливье Накаш, Эрик Толедано"],"description":"Богатый аристократ, парализованный после несчастного случая, нанимает в помощники молодого парня из бедного пригорода без опыта, и между непохожими друг на друга людьми возникает крепкая дружба. Французский фильм основан на реальной истории и стал одним из самых кассовых французских фильмов в мире.","fact":"В основу сюжета легла реальная история дружбы предпринимателя Филиппа Поццо ди Борго и его помощника.","wiki_en":"The Intouchables"},{"name":"Амели","emoji":"🎨","meta":["романтическая комедия","2001","Жан-Пьер Жёне"],"description":"Застенчивая официантка парижского кафе решает тайно и изобретательно вмешиваться в жизни окружающих, устраивая маленькие добрые чудеса, оставаясь при этом в тени сама. Фильм известен яркой стилизованной картинкой Парижа и стал визитной карточкой французского кино рубежа веков.","fact":"Многие сцены фильма снимались в реальном парижском кафе на Монмартре, которое после премьеры стало туристической достопримечательностью.","wiki_en":"Amélie"},{"name":"Жизнь прекрасна","emoji":"🎪","meta":["трагикомедия","1997","Роберто Бениньи"],"description":"Еврейский отец в оккупированной нацистами Италии, оказавшись вместе с маленьким сыном в концлагере, превращает происходящий кошмар в придуманную для ребёнка игру, чтобы уберечь его психику. Итальянский фильм соединяет комедию и трагедию Холокоста, что стало предметом споров критиков.","fact":"Роберто Бениньи выступил режиссёром, соавтором сценария и исполнителем главной роли, за которую получил «Оскар».","wiki_en":"Life Is Beautiful"},{"name":"Хороший, плохой, злой","emoji":"🤠","meta":["вестерн","1966","Серджо Леоне"],"description":"Трое охотников за наживой — расчётливый стрелок, безжалостный наёмник и хитрый мошенник — идут по следу закопанного в безымянной могиле золота времён Гражданской войны в США. Итальянский вестерн Серджо Леоне с музыкой Эннио Морриконе завершает «долларовую трилогию».","fact":"Знаменитая финальная трёхсторонняя дуэль фильма снята с почти музыкальным монтажом крупных планов лиц и рук героев.","wiki_en":"The Good, the Bad and the Ugly"},{"name":"Психо","emoji":"🚿","meta":["психологический триллер","1960","Альфред Хичкок"],"description":"Молодая женщина, скрывающаяся после кражи крупной суммы денег, останавливается в уединённом придорожном мотеле, которым управляет странный молодой человек, живущий под гнётом властной матери. Фильм Хичкока перевернул представления о том, как строится напряжение в триллере.","fact":"Сцена убийства в душе, ставшая одной из самых знаменитых в истории кино, снималась несколько дней ради считаных секунд экранного времени.","wiki_en":"Psycho (1960 film)"},{"name":"Сияние","emoji":"🪓","meta":["психологические ужасы","1980","Стэнли Кубрик"],"description":"Писатель устраивается смотрителем уединённого горного отеля на зимний сезон вместе с семьёй, но постепенно поддаётся воздействию тёмной силы, обитающей в стенах здания. Экранизация романа Стивена Кинга стала одной из самых атмосферных и цитируемых картин в истории жанра ужасов.","fact":"Стивен Кинг, автор романа-первоисточника, долгое время был недоволен трактовкой Кубрика и считал её слишком холодной.","wiki_en":"The Shining (film)"},{"name":"2001 год: Космическая одиссея","emoji":"🪐","meta":["фантастика","1968","Стэнли Кубрик"],"description":"Загадочный чёрный монолит подталкивает развитие человечества от первобытных предков до полёта к Юпитеру, где экипаж космического корабля вступает в конфликт с взбунтовавшимся искусственным интеллектом. Фильм Кубрика известен почти медитативным темпом и новаторскими визуальными эффектами.","fact":"Многие спецэффекты фильма, снятые ещё до высадки человека на Луну, до сих пор выглядят убедительно без компьютерной графики.","wiki_en":"2001: A Space Odyssey (film)"},{"name":"Заводной апельсин","emoji":"👁️","meta":["антиутопия","1971","Стэнли Кубрик"],"description":"Юный предводитель уличной банды в антиутопическом Лондоне подвергается экспериментальному государственному лечению, призванному подавить в нём склонность к насилию. Экранизация романа Энтони Бёрджесса вызвала бурные споры из-за откровенного изображения жестокости.","fact":"После волны критики и подражательных актов насилия сам Кубрик добился прекращения проката фильма в Великобритании на много лет.","wiki_en":"A Clockwork Orange (film)"},{"name":"Касабланка","emoji":"🍸","meta":["мелодрама","1942","Майкл Кёртис"],"description":"Владелец бара в марокканской Касабланке, находящейся под властью коллаборационистского правительства Виши, вновь встречает бывшую возлюбленную, которая приезжает с мужем-участником Сопротивления в поисках спасения от нацистов. Фильм эпохи Второй мировой войны стал эталоном голливудской мелодрамы.","fact":"Фраза «Здесь начинается прекрасная дружба» и многие другие реплики фильма вошли в число самых цитируемых в истории кино.","wiki_en":"Casablanca (film)"},{"name":"Унесённые ветром","emoji":"🌾","meta":["историческая мелодрама","1939","Виктор Флеминг"],"description":"Своенравная дочь плантатора переживает Гражданскую войну в США и её последствия, отчаянно борясь за сохранение дома и добиваясь мужчин, которых не может получить. Масштабная экранизация романа Маргарет Митчелл долгое время оставалась самым кассовым фильмом в истории.","fact":"С учётом инфляции фильм по сей день считается одним из самых кассовых в истории кинопроката.","wiki_en":"Gone with the Wind (film)"},{"name":"Волшебник страны Оз","emoji":"🌈","meta":["мюзикл","1939","Виктор Флеминг"],"description":"Девочку из Канзаса вместе с домиком уносит ураганом в волшебную страну, где ей предстоит по дороге из жёлтого кирпича добраться до Изумрудного города, чтобы найти способ вернуться домой. Один из первых цветных голливудских блокбастеров стал классикой семейного кино.","fact":"Переход фильма от чёрно-белого Канзаса к цветной стране Оз стал одним из самых знаменитых визуальных приёмов в истории кино.","wiki_en":"The Wizard of Oz (1939 film)"},{"name":"Завтрак у Тиффани","emoji":"💎","meta":["романтическая комедия","1961","Блейк Эдвардс"],"description":"Эксцентричная светская девушка Холли Голайтли, живущая мечтами о роскоши и избегающая привязанностей, заводит дружбу с новым соседом по дому в Нью-Йорке. Экранизация повести Трумена Капоте сделала образ героини в чёрном платье и с длинным мундштуком одной из икон стиля XX века.","fact":"Чёрное платье героини от Живанши в одной из самых узнаваемых сцен фильма позже было продано на аукционе за рекордную сумму.","wiki_en":"Breakfast at Tiffany's (film)"},{"name":"Римские каникулы","emoji":"🛵","meta":["романтическая комедия","1953","Уильям Уайлер"],"description":"Уставшая от протокола европейская принцесса сбегает на одну ночь из-под опеки во время визита в Рим и, не раскрывая своего титула, проводит день с американским журналистом. Фильм принёс Одри Хепбёрн «Оскар» за первую большую роль в Голливуде и сделал Рим одной из главных романтических декораций в кино.","fact":"Поездка героев на мотороллере по Риму после выхода фильма резко повысила популярность вида транспорта Vespa.","wiki_en":"Roman Holiday"},{"name":"Пролетая над гнездом кукушки","emoji":"🏥","meta":["драма","1975","Милош Форман"],"description":"Мужчина, симулирующий психическое расстройство, чтобы избежать тюрьмы, попадает в психиатрическую больницу и постепенно восстаёт против деспотичных порядков, установленных суровой старшей медсестрой. Экранизация романа Кена Кизи стала одной из немногих картин, получивших все пять главных «Оскаров».","fact":"Съёмки проходили в настоящей психиатрической больнице в Орегоне, а её главный врач даже сыграл в фильме небольшую роль.","wiki_en":"One Flew Over the Cuckoo's Nest (film)"},{"name":"Апокалипсис сегодня","emoji":"🚁","meta":["военная драма","1979","Фрэнсис Форд Коппола"],"description":"Американский капитан получает секретное задание найти и ликвидировать одичавшего в джунглях полковника, создавшего собственный культ посреди войны во Вьетнаме. Съёмки фильма, вдохновлённого повестью Джозефа Конрада, сами превратились в изматывающую эпопею, растянувшуюся на годы.","fact":"Съёмки фильма настолько затянулись и вышли из-под контроля, что об этом позже сняли отдельный документальный фильм.","wiki_en":"Apocalypse Now"},{"name":"Семь самураев","emoji":"⚔️","meta":["приключенческая драма","1954","Акира Куросава"],"description":"Бедная японская деревня нанимает семерых странствующих самураев, чтобы защититься от регулярных набегов разбойников, и те учат крестьян обороне. Эпический фильм Акиры Куросавы оказал огромное влияние на мировое кино и лёг в основу вестерна «Великолепная семёрка».","fact":"На момент выхода это был один из самых дорогих и долгих в производстве фильмов в истории японского кино.","wiki_en":"Seven Samurai"},{"name":"Ирония судьбы, или С лёгким паром!","emoji":"🎄","meta":["новогодняя комедия","1975","Эльдар Рязанов"],"description":"Компания друзей в новогоднюю ночь по традиции ходит в баню, и подвыпившего героя по ошибке отправляют не на тот рейс, из-за чего он попадает в чужой город и чужую квартиру с одинаковым адресом. Советская новогодняя комедия десятилетиями остаётся неизменным атрибутом праздничного телевечера.","fact":"Песни в фильме звучат на стихи Цветаевой, Пастернака, Ахмадулиной и других поэтов, а музыку к ним написал Микаэл Таривердиев.","wiki_en":"The Irony of Fate"},{"name":"Бриллиантовая рука","emoji":"💎","meta":["эксцентрическая комедия","1968","Леонид Гайдай"],"description":"Советского туриста по ошибке принимают за курьера контрабандистов и во время заграничного круиза незаметно закладывают ему в гипс на руке партию драгоценностей. Комедия Леонида Гайдая разошлась на цитаты и песни и остаётся одной из самых любимых советских кинокомедий.","fact":"Песня «Остров невезения» из фильма стала настолько популярной, что зажила отдельной от картины жизнью.","wiki_en":"The Diamond Arm"},{"name":"Операция «Ы» и другие приключения Шурика","emoji":"🧱","meta":["эксцентрическая комедия","1965","Леонид Гайдай"],"description":"Три отдельные новеллы рассказывают о незадачливом студенте Шурике, который то помогает бороться с тунеядцем на стройке, то сдаёт экзамен, то срывает план мошенников по ограблению склада. Фильм Гайдая подарил зрителям одну из самых известных ролей троицы жуликов — Труса, Балбеса и Бывалого.","fact":"Трио жуликов — Трус, Балбес и Бывалый — появилось у Гайдая ещё в короткометражках начала 1960-х и стало самостоятельным комическим брендом.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Кавказская пленница","emoji":"🐴","meta":["эксцентрическая комедия","1966","Леонид Гайдай"],"description":"Приехавший на Кавказ студент Шурик случайно оказывается вовлечён в похищение девушки, которую местный чиновник хочет взять в жёны против её воли, и берётся её спасать. Комедия Леонида Гайдая с той же троицей жуликов стала одной из самых цитируемых советских картин.","fact":"Реплики фильма, включая тост про долгожителей и фразу «птичку жалко», давно живут в русском языке отдельно от картины.","wiki_en":"Kidnapping, Caucasian Style"},{"name":"Иван Васильевич меняет профессию","emoji":"👑","meta":["эксцентрическая комедия","1973","Леонид Гайдай"],"description":"Самодельная машина времени инженера-изобретателя случайно переносит управдома в эпоху Ивана Грозного, а самого царя — в советскую квартиру, что приводит к череде комических путаниц. Экранизация пьесы Михаила Булгакова стала одной из самых любимых советских комедий о путешествиях во времени.","fact":"И грозного царя, и робкого управдома Буншу в фильме играет один и тот же актёр — Юрий Яковлев.","wiki_en":"Ivan Vasilievich: Back to the Future"},{"name":"Джентльмены удачи","emoji":"🎩","meta":["криминальная комедия","1971","Александр Серый"],"description":"Добродушного заведующего детским садом, похожего на матёрого уголовника, привлекают к операции, чтобы он под видом преступника выведал у сокамерников место спрятанного похищенного золотого шлема. Советская комедия о перевоспитании жуликов быстро разошлась на крылатые фразы.","fact":"Многие реплики фильма, включая «Кто ж его посадит, он же памятник», прочно вошли в разговорную речь.","wiki_en":"Gentlemen of Fortune"},{"name":"Москва слезам не верит","emoji":"🏙️","meta":["мелодрама","1980","Владимир Меньшов"],"description":"История трёх молодых провинциалок, приехавших покорять Москву в конце 1950-х, показанная затем спустя двадцать лет, когда их судьбы сложились совсем по-разному. Фильм стал одним из самых любимых в СССР и получил «Оскар» за лучший фильм на иностранном языке.","fact":"Режиссёр Владимир Меньшов не смог поехать на церемонию за наградой и получил свою статуэтку лишь много лет спустя.","wiki_en":"Moscow Does Not Believe in Tears"},{"name":"Служебный роман","emoji":"💼","meta":["лирическая комедия","1977","Эльдар Рязанов"],"description":"Строгая и незаметная для окружающих директриса статистического учреждения неожиданно для себя влюбляется в нового скромного сотрудника, который решает помочь ей стать увереннее и привлекательнее. Советская комедия о позднем чувстве на фоне бюрократической рутины стала одной из самых пересматриваемых.","fact":"Основой фильма стала пьеса «Сослуживцы», написанная Эльдаром Рязановым вместе с Эмилем Брагинским и ранее шедшая в театрах.","wiki_en":"Office Romance"},{"name":"Любовь и голуби","emoji":"🕊️","meta":["лирическая комедия","1984","Владимир Меньшов"],"description":"Простой семьянин из глубинки, поехав на курорт, неожиданно для себя увлекается яркой курортницей и на время уходит из семьи, а жена и дети пытаются вернуть его домой. Комедия по мотивам пьесы стала одной из самых народно любимых советских картин о деревенской жизни.","fact":"Деревенского выпивоху дядю Митю сыграл Сергей Юрский — актёр совсем другого, интеллигентного амплуа, которого ради роли сильно загримировали.","wiki_en":"Love and Doves"},{"name":"Белое солнце пустыни","emoji":"🏜️","meta":["истерн","1970","Владимир Мотыль"],"description":"Демобилизованный красноармеец Сухов, возвращаясь домой через среднеазиатскую пустыню, вынужден взять под опеку целый гарем сбежавшего от преследования басмача и защищать его от бывшего хозяина. Фильм в жанре советского истерна стал классикой и традиционно смотрится космонавтами перед стартом.","fact":"Песню «Ваше благородие, госпожа удача» на стихи Булата Окуджавы спел Павел Луспекаев, сыгравший таможенника Верещагина.","wiki_en":"White Sun of the Desert"},{"name":"Брат","emoji":"🔫","meta":["криминальная драма","1997","Алексей Балабанов"],"description":"Демобилизованный из армии парень приезжает в Петербург к старшему брату и постепенно втягивается в криминальные разборки девяностых, действуя по своим представлениям о справедливости. Фильм Алексея Балабанова стал одним из главных портретов постсоветской эпохи и культовой картиной поколения.","fact":"Музыку группы «Наутилус Помпилиус» из фильма после выхода картины стали прочно ассоциировать с образом главного героя.","wiki_en":"Brother (1997 film)"},{"name":"Брат 2","emoji":"✈️","meta":["криминальная драма","2000","Алексей Балабанов"],"description":"Герой первого фильма отправляется в Америку, чтобы разобраться в судьбе бывшего сослуживца и восстановить справедливость, сталкиваясь с чужой и не всегда понятной ему страной. Сиквел культовой картины Балабанова подарил зрителям ещё больше крылатых фраз и закрепил статус фильма как поколенческого высказывания.","fact":"Диалог о том, в чём сила — в деньгах или в правде, стал одной из самых узнаваемых сцен в русском кино.","wiki_en":"Brother 2"},{"name":"Сталкер","emoji":"🌫️","meta":["философская фантастика","1979","Андрей Тарковский"],"description":"Проводник по прозвищу Сталкер ведёт писателя и учёного через таинственную и опасную Зону к комнате, где, по легенде, исполняются самые сокровенные желания. Экранизация повести братьев Стругацких превратилась у Тарковского в медитативную притчу о вере, желании и человеческой природе.","fact":"Значительную часть материала пришлось переснимать заново из-за брака при обработке плёнки, и производство растянулось на годы.","wiki_en":"Stalker (1979 film)"},{"name":"Гражданин Кейн","emoji":"📰","meta":["драма","1941","Орсон Уэллс"],"description":"Дебютный полнометражный фильм Орсона Уэллса о взлёте и падении газетного магната Чарльза Фостера Кейна, рассказанный через воспоминания знавших его людей. Картина совершила революцию в операторской работе, монтаже и построении сюжета и десятилетиями возглавляла списки лучших фильмов всех времён.","fact":"Загадочное предсмертное слово «Роузбад» стало одним из самых обсуждаемых символов в истории кино — оно так и остаётся непонятным героям фильма почти до самого финала.","wiki_en":"Citizen Kane"},{"name":"На набережной","emoji":"⚓","meta":["драма","1954","Элиа Казан"],"description":"Фильм Элиа Казана о бывшем боксёре Терри Мэллое, докере из портового города, который оказывается зажат между профсоюзной мафией и собственной совестью. Марлон Брандо сыграл одну из самых знаковых ролей своей карьеры, а картина получила восемь «Оскаров», включая награду за лучший фильм.","fact":"Сцена разговора Терри с братом в такси считается одной из самых цитируемых и разобранных актёрских сцен в истории кино.","wiki_en":"On the Waterfront"},{"name":"Лоуренс Аравийский","emoji":"🐪","meta":["эпос","1962","Дэвид Лин"],"description":"Эпическая биографическая драма Дэвида Лина о британском офицере Томасе Эдварде Лоуренсе, который во время Первой мировой войны объединил арабские племена в восстании против Османской империи. Фильм прославился масштабными съёмками в пустыне и получил семь «Оскаров», включая приз за лучший фильм.","fact":"Роль Лоуренса сделала почти неизвестного театрального актёра Питера О'Тула звездой и принесла ему первую из восьми номинаций на «Оскар», ни одну из которых он так и не превратил в награду.","wiki_en":"Lawrence of Arabia (film)"},{"name":"Бен-Гур","emoji":"🏇","meta":["историческая драма","1959","Уильям Уайлер"],"description":"Экранизация романа Лью Уоллеса о знатном иудее Джуде Бен-Гуре, преданном другом детства и обращённом в рабство, который возвращается, чтобы добиться справедливости во времена Христа. Фильм знаменит грандиозной сценой гонки на колесницах и установил рекорд по числу «Оскаров» — одиннадцать.","fact":"Сцену гонки на колесницах снимали несколько недель на огромной арене, выстроенной для фильма на римской студии «Чинечитта».","wiki_en":"Ben-Hur (1959 film)"},{"name":"Вестсайдская история","emoji":"💃","meta":["мюзикл","1961","Роберт Уайз"],"description":"Музыкальная драма о вражде двух уличных банд Нью-Йорка — «Ракет» и «Акул», — на фоне которой разворачивается запретная любовь Тони и Марии в духе шекспировских «Ромео и Джульетты». Фильм соединил бродвейские хиты Леонарда Бернстайна с яркой хореографией и получил десять «Оскаров».","fact":"Хореографию к фильму поставил Джером Роббинс, ставший сорежиссёром картины наряду с Робертом Уайзом.","wiki_en":"West Side Story (1961 film)"},{"name":"Звуки музыки","emoji":"🎶","meta":["мюзикл","1965","Роберт Уайз"],"description":"История послушницы Марии, которая становится гувернанткой семерых детей строгого австрийского капитана фон Траппа и объединяет семью с помощью песен, а затем помогает ей бежать от аннексировавших Австрию нацистов. Мюзикл на музыку Роджерса и Хаммерстайна стал одним из самых кассовых фильмов своего времени.","fact":"Сцены с альпийскими лугами в начале фильма снимали в окрестностях Зальцбурга, которые с тех пор стали туристической достопримечательностью.","wiki_en":"The Sound of Music (film)"},{"name":"Ребекка","emoji":"🏚️","meta":["триллер","1940","Альфред Хичкок"],"description":"Первый голливудский фильм Альфреда Хичкока по роману Дафны Дюморье: молодая жена богатого вдовца переезжает в его поместье Мандерли и постоянно чувствует незримое присутствие его покойной первой супруги Ребекки. Атмосфера тайны и психологического давления принесла фильму «Оскар» за лучший фильм.","fact":"Имя главной героини, от лица которой ведётся рассказ, так ни разу и не называется на протяжении всего фильма.","wiki_en":"Rebecca (1940 film)"},{"name":"Головокружение","emoji":"🌀","meta":["триллер","1958","Альфред Хичкок"],"description":"Детектив, страдающий боязнью высоты, влюбляется в загадочную женщину, за которой его наняли следить, и это наваждение затягивает его в сеть обмана. Хичкок использовал новаторский приём одновременного наезда камеры и обратного трансфокуса, который позже стали называть «эффектом головокружения».","fact":"При выходе картину приняли прохладно, а спустя полвека опрос критиков журнала Sight & Sound поставил её на первое место среди лучших фильмов всех времён.","wiki_en":"Vertigo (film)"},{"name":"Окно во двор","emoji":"🔭","meta":["триллер","1954","Альфред Хичкок"],"description":"Прикованный к инвалидному креслу фотограф от скуки наблюдает за жизнью соседей через окно своей квартиры и начинает подозревать одного из них в убийстве жены. Почти всё действие фильма разворачивается в пределах одной комнаты, что делает его одним из самых камерных триллеров Хичкока.","fact":"Все декорации двора и соседних домов были построены в павильоне студии как единая масштабная конструкция.","wiki_en":"Rear Window"},{"name":"Птицы","emoji":"🐦","meta":["ужасы","1963","Альфред Хичкок"],"description":"В прибрежном калифорнийском городке птицы без всякой видимой причины начинают массово нападать на людей, превращая размеренную жизнь местных жителей в кошмар. Хичкок сознательно отказался от музыкального сопровождения, заменив его звуками птичьих криков и хлопающих крыльев.","fact":"Для сцен нападений использовали как механических, так и живых птиц, которых актёрам буквально прикрепляли к одежде леской.","wiki_en":"The Birds (film)"},{"name":"В джазе только девушки","emoji":"🎷","meta":["комедия","1959","Билли Уайлдер"],"description":"Два музыканта случайно становятся свидетелями бандитской разборки и, спасаясь от мафии, переодеваются в женщин и присоединяются к женскому джазовому оркестру. Классика комедийного жанра с Мэрилин Монро в главной роли считается одной из лучших комедий в истории американского кино.","fact":"Мэрилин Монро потребовалось множество дублей, чтобы произнести всего одну простую фразу — это стало киношной легендой.","wiki_en":"Some Like It Hot"},{"name":"Мост через реку Квай","emoji":"🌉","meta":["военная драма","1957","Дэвид Лин"],"description":"Британские военнопленные в японском лагере во время Второй мировой войны вынуждены строить железнодорожный мост, и их командир из принципа превращает эту стройку в дело чести, забывая, что мост послужит врагу. Фильм получил семь «Оскаров», включая награды за лучший фильм и режиссуру.","fact":"Знаменитый марш «Полковник Боуги», который насвистывают пленные, стал одной из самых узнаваемых кинематографических мелодий.","wiki_en":"The Bridge on the River Kwai"},{"name":"Из Африки","emoji":"🦁","meta":["драма","1985","Сидни Поллак"],"description":"Основанная на воспоминаниях датской писательницы Карен Бликсен история её жизни на кофейной плантации в Кении начала XX века и романа с охотником-авантюристом Дэнисом Финч-Хэттоном. Фильм с Мэрил Стрип и Робертом Редфордом получил семь «Оскаров», включая приз за лучший фильм.","fact":"Настоящий дом Карен Бликсен в Кении сегодня работает как музей, посвящённый писательнице и этому фильму.","wiki_en":"Out of Africa (film)"},{"name":"Танцующий с волками","emoji":"🐺","meta":["вестерн","1990","Кевин Костнер"],"description":"Офицер армии Союза во время Гражданской войны в США отправляется служить на дальний пограничный пост и постепенно сближается с племенем сиу, перенимая их образ жизни и ценности. Режиссёрский дебют Кевина Костнера, сыгравшего и главную роль, получил семь «Оскаров».","fact":"Значительная часть диалогов в фильме звучит на языке лакота с английскими субтитрами — редкий случай для голливудского блокбастера.","wiki_en":"Dances with Wolves"},{"name":"Английский пациент","emoji":"🏜️","meta":["драма","1996","Энтони Мингелла"],"description":"В разрушенном войной итальянском монастыре медсестра ухаживает за обгоревшим до неузнаваемости пациентом, чья личность окутана тайной, и постепенно из его воспоминаний складывается история трагической любви на фоне пустынь Северной Африки. Экранизация романа Майкла Ондатже получила девять «Оскаров».","fact":"Пустынные сцены снимали в Сахаре на юге Туниса, а эпизоды в монастыре — в настоящей старинной обители в Тоскане.","wiki_en":"The English Patient (film)"},{"name":"Амадей","emoji":"🎼","meta":["драма","1984","Милош Форман"],"description":"История взаимоотношений композитора Антонио Сальери и гениального, но эксцентричного Вольфганга Амадея Моцарта, рассказанная от лица постаревшего Сальери, мучимого завистью и раскаянием. Фильм Милоша Формана получил восемь «Оскаров», включая награду за лучший фильм.","fact":"Несмотря на драматический сюжет о соперничестве, историки считают версию вражды Сальери и Моцарта художественным вымыслом.","wiki_en":"Amadeus (film)"},{"name":"Однажды в Америке","emoji":"🎩","meta":["криминальная драма","1984","Серджо Леоне"],"description":"Постаревший гангстер по прозвищу Лапша возвращается в Нью-Йорк спустя десятилетия и вспоминает свою юность на улицах еврейского квартала, дружбу и предательство, связавшие его с бандой друзей детства. Последний фильм Серджо Леоне охватывает несколько десятилетий истории и считается его эпическим завещанием.","fact":"Оригинальная версия фильма длится почти четыре часа, но в американском прокате её сильно сократили и перемонтировали в хронологическом порядке.","wiki_en":"Once Upon a Time in America"},{"name":"Изгоняющий дьявола","emoji":"😈","meta":["ужасы","1973","Уильям Фридкин"],"description":"После необъяснимых перемен в поведении двенадцатилетней дочери актриса обращается за помощью к священникам, которые проводят обряд изгнания демона из тела девочки. Фильм Уильяма Фридкина стал одним из первых хорроров, номинированных на «Оскар» за лучший фильм, и породил волну картин об одержимости.","fact":"Во время премьерных показов у части зрителей случались обмороки — настолько сильным было воздействие фильма.","wiki_en":"The Exorcist"},{"name":"Кинг-Конг","emoji":"🦍","meta":["приключения","1933","Купер и Шодсак"],"description":"Съёмочная группа отправляется на затерянный остров, где обнаруживает гигантскую обезьяну Кинг-Конга, почитаемую местными жителями как божество, и привозит его в Нью-Йорк на потеху публике. Фильм 1933 года стал прорывом в области комбинированных съёмок и покадровой анимации и породил целую киновселенную.","fact":"Модель Кинг-Конга для покадровой съёмки была всего около полуметра высотой, хотя на экране выглядит гигантской.","wiki_en":"King Kong (1933 film)"},{"name":"Линкольн","emoji":"🎩","meta":["биографическая драма","2012","Стивен Спилберг"],"description":"Фильм Стивена Спилберга сосредоточен на последних месяцах жизни президента Авраама Линкольна, когда он ведёт политическую борьбу за принятие тринадцатой поправки к Конституции США, отменяющей рабство. Дэниел Дэй-Льюис получил за роль Линкольна третий в своей карьере «Оскар».","fact":"Дэниел Дэй-Льюис готовился к роли, изучая манеру речи и походку Линкольна по историческим описаниям современников.","wiki_en":"Lincoln (film)"},{"name":"Реальная любовь","emoji":"❤️","meta":["романтическая комедия","2003","Ричард Кёртис"],"description":"Рождественская комедия переплетает истории десятка лондонцев — от премьер-министра до школьника, — каждый из которых по-своему ищет или теряет любовь в преддверии праздника. Многослойный ансамблевый фильм со звёздным составом стал одной из самых любимых рождественских картин.","fact":"Несмотря на скромный бюджет, фильм собрал в мировом прокате в несколько раз больше вложенных в него денег и ежегодно возвращается на экраны под Рождество.","wiki_en":"Love Actually"},{"name":"Дневник памяти","emoji":"💌","meta":["мелодрама","2004","Ник Кассаветис"],"description":"Пожилой мужчина читает пациентке дома престарелых историю любви двух молодых людей из разных социальных слоёв, разлучённых войной и обстоятельствами, но пронёсших чувства через годы. Экранизация романа Николаса Спаркса стала одной из самых популярных мелодрам 2000-х.","fact":"Фильм снимали в Южной Каролине, хотя действие книги-первоисточника происходит в соседней Северной Каролине.","wiki_en":"The Notebook (2004 film)"},{"name":"Крёстный отец 2","emoji":"🍷","meta":["криминальная драма","1974","Фрэнсис Форд Коппола"],"description":"Продолжение саги о семье Корлеоне сплетает две параллельные линии — становление молодого Вито Корлеоне на рубеже веков и укрепление власти его сына Майкла в послевоенной Америке. Фильм стал первым сиквелом в истории, получившим «Оскар» за лучший фильм.","fact":"Роберт Де Ниро получил «Оскар» за роль молодого Вито Корлеоне, хотя большая часть его реплик звучит на сицилийском диалекте.","wiki_en":"The Godfather Part II"},{"name":"Престиж","emoji":"🎩","meta":["мистическая драма","2006","Кристофер Нолан"],"description":"Два лондонских фокусника конца XIX века превращают профессиональное соперничество в изматывающую личную войну, соревнуясь в изобретении всё более опасных иллюзий. Кристофер Нолан выстроил фильм как сложную головоломку с несколькими временными линиями, разгадка которой приходит только в финале.","fact":"Название фильма отсылает к третьему, завершающему акту фокуса, о котором прямо рассуждают сами герои картины.","wiki_en":"The Prestige (film)"},{"name":"Дюнкерк","emoji":"🪖","meta":["военная драма","2017","Кристофер Нолан"],"description":"Фильм воссоздаёт эвакуацию британских и союзных войск с французского побережья в 1940 году, когда армия оказалась прижата к морю немецкими войсками. Нолан рассказывает историю через три сюжетные линии — сушу, море и воздух, — разворачивающиеся в разном временном масштабе.","fact":"Для съёмок воздушных боёв использовали настоящие самолёты времён Второй мировой войны, а не только компьютерную графику.","wiki_en":"Dunkirk (2017 film)"},{"name":"Довод","emoji":"⏳","meta":["фантастика","2020","Кристофер Нолан"],"description":"Безымянный агент получает задание предотвратить угрозу, способную привести к концу света, и для этого осваивает технологию обращения хода времени, позволяющую двигаться в прошлое как в зеркальном отражении. Один из самых визуально изощрённых и сюжетно запутанных фильмов Кристофера Нолана.","fact":"Многие трюковые сцены с «обратным» движением снимали, заставляя каскадёров реально двигаться назад, а не используя обратную прокрутку плёнки.","wiki_en":"Tenet (film)"},{"name":"Тёмный рыцарь: Возрождение легенды","emoji":"🦇","meta":["супергероика","2012","Кристофер Нолан"],"description":"Спустя восемь лет после событий предыдущего фильма постаревший и разочарованный Брюс Уэйн вынужден вновь надеть плащ Бэтмена, когда Готэму угрожает безжалостный наёмник Бейн. Заключительная часть трилогии Кристофера Нолана о Бэтмене стала одним из самых кассовых супергеройских фильмов своего времени.","fact":"Для роли Бейна Том Харди разработал особый низкий голос, который пришлось частично переозвучивать после жалоб зрителей на неразборчивость.","wiki_en":"The Dark Knight Rises"},{"name":"Человек из стали","emoji":"🦸","meta":["супергероика","2013","Зак Снайдер"],"description":"Фильм переосмысливает происхождение Супермена: выросший на Земле пришелец с планеты Криптон по имени Кларк Кент учится принимать свою инопланетную природу и решает, как использовать сверхспособности во благо человечества. Картина Зака Снайдера перезапустила киновселенную DC.","fact":"Костюм Супермена в этом фильме впервые за долгое время отказался от привычных красных трусов поверх трико.","wiki_en":"Man of Steel (film)"},{"name":"Бэтмен против Супермена: На заре справедливости","emoji":"⚔️","meta":["супергероика","2016","Зак Снайдер"],"description":"Обеспокоенный разрушительной мощью Супермена, Бэтмен решает, что должен остановить его, пока тот не стал угрозой человечеству, и их противостояние оборачивается эпической схваткой двух самых известных супергероев DC. Фильм также представил зрителям киновселенной первую версию Чудо-женщины.","fact":"Это первое появление Чудо-женщины на большом экране в исполнении Галь Гадот, ставшей затем звездой отдельной франшизы.","wiki_en":"Batman v Superman: Dawn of Justice"},{"name":"Лига справедливости","emoji":"🦸‍♂️","meta":["супергероика","2017","Зак Снайдер"],"description":"Бэтмен и Чудо-женщина собирают команду супергероев — Флэша, Аквамена и Киборга, — чтобы противостоять инопланетному захватчику Степному Волку, который пришёл за источниками силы, спрятанными на Земле. Фильм впервые объединил ключевых героев вселенной DC в одной картине.","fact":"Из-за ухода режиссёра Зака Снайдера часть съёмок и монтажа завершал Джосс Уидон, а спустя годы вышла отдельная авторская версия фильма Снайдера.","wiki_en":"Justice League (film)"},{"name":"Аквамен","emoji":"🔱","meta":["супергероика","2018","Джеймс Ван"],"description":"Наполовину человек, наполовину атлант Артур Карри узнаёт, что является законным наследником подводного трона Атлантиды, и должен предотвратить войну между океаном и сушей, которую готовит его сводный брат. Фильм Джеймса Вана стал одним из самых кассовых в истории вселенной DC.","fact":"Многие подводные сцены снимали в специальных резервуарах, симулируя невесомость с помощью тросовой системы, а не реальной воды.","wiki_en":"Aquaman (film)"},{"name":"Чудо-женщина","emoji":"🛡️","meta":["супергероика","2017","Патти Дженкинс"],"description":"Выросшая на острове женщин-воительниц амазонка Диана покидает свой дом, чтобы помочь остановить Первую мировую войну, и впервые сталкивается с миром людей вне защищённого рая Темискиры. Фильм Патти Дженкинс стал первой крупнобюджетной супергеройской картиной с женщиной-режиссёром во главе.","fact":"Галь Гадот проходила службу в израильской армии до актёрской карьеры, что помогло ей в подготовке к боевым сценам.","wiki_en":"Wonder Woman (2017 film)"},{"name":"Отряд самоубийц","emoji":"💣","meta":["супергероика","2016","Дэвид Эйер"],"description":"Правительственная организация собирает команду опасных суперзлодеев из тюрьмы, обещая им сокращение сроков в обмен на выполнение смертельно опасных секретных операций. Фильм Дэвида Эйера представил зрителям культовых злодеев вселенной DC, включая Джокера и Харли Квинн.","fact":"Марго Робби готовилась к роли Харли Квинн, изучая архивные комиксы и мультсериалы о персонаже 1990-х годов.","wiki_en":"Suicide Squad (2016 film)"},{"name":"Логан","emoji":"🐾","meta":["супергероика","2017","Джеймс Мэнголд"],"description":"Постаревший и утративший способность к регенерации Логан скрывается в приграничье вместе с больным профессором Ксавье, пока не встречает девочку с силами, похожими на его собственные. Мрачный и жёсткий фильм Джеймса Мэнголда получил рейтинг R и номинацию на «Оскар» за лучший адаптированный сценарий.","fact":"Помимо обычной версии в прокат выпустили и полностью чёрно-белую — под названием Logan Noir.","wiki_en":"Logan (film)"},{"name":"Люди Икс","emoji":"🧬","meta":["супергероика","2000","Брайан Сингер"],"description":"В недалёком будущем люди-мутанты с необычными способностями скрываются от враждебно настроенного общества, а профессор Ксавье собирает команду молодых мутантов для защиты мирного сосуществования людей и мутантов. Фильм положил начало одной из самых долгоживущих супергеройских киносерий.","fact":"Костюмы героев сознательно сделали в чёрной коже вместо ярких комиксовых трико, чтобы фильм выглядел более реалистично.","wiki_en":"X-Men (film)"},{"name":"Люди Икс 2","emoji":"🧬","meta":["супергероика","2003","Брайан Сингер"],"description":"Нападение мутанта на президента США даёт военному полковнику повод начать масштабную операцию против всех мутантов, вынуждая Людей Икс объединиться со своими врагами ради общего выживания. Сиквел значительно расширил мир первого фильма и считается одним из лучших в серии.","fact":"Многие критики и фанаты называют этот фильм одним из редких сиквелов, превзошедших оригинал.","wiki_en":"X2 (film)"},{"name":"Росомаха: Бессмертный","emoji":"🗡️","meta":["супергероика","2013","Джеймс Мэнголд"],"description":"Логан отправляется в Японию, куда его приглашает умирающий магнат, которому он когда-то спас жизнь, и оказывается втянут в схватку за наследство, из-за которой впервые может утратить свой дар бессмертия. Фильм Джеймса Мэнголда сместил фокус с масштабных битв на личную драму героя.","fact":"Сюжет фильма частично основан на культовой серии комиксов о Росомахе авторства Криса Клермонта и Фрэнка Миллера.","wiki_en":"The Wolverine (film)"},{"name":"Капитан Америка: Первый мститель","emoji":"🛡️","meta":["супергероика","2011","Джо Джонстон"],"description":"Хилый, но отважный юноша Стив Роджерс во время Второй мировой войны становится подопытным для секретного эксперимента, превращающего его в суперсолдата, и вступает в борьбу с нацистской организацией «Гидра». Фильм заложил основу для дальнейшего появления Капитана Америки в кинематографической вселенной Marvel.","fact":"Худого Стива Роджерса получили цифровым «уменьшением» Криса Эванса и съёмками с более щуплым дублёром, к телу которого подставляли лицо актёра.","wiki_en":"Captain America: The First Avenger"},{"name":"Тор","emoji":"🔨","meta":["супергероика","2011","Кеннет Брана"],"description":"Высокомерный наследник асгардского престола Тор за нарушение мира изгнан отцом на Землю без своих божественных сил и молота Мьёльнира и должен доказать, что достоин вернуть себе титул. Фильм познакомил кинозрителей со скандинавской мифологией в рамках вселенной Marvel.","fact":"Крис Хемсворт набрал заметную мышечную массу специально для роли, кардинально изменив физическую форму за несколько месяцев подготовки.","wiki_en":"Thor (film)"},{"name":"Доктор Стрэндж","emoji":"🌀","meta":["супергероика","2016","Скотт Дерриксон"],"description":"Блестящий, но самоуверенный нейрохирург Стивен Стрэндж после аварии, лишившей его рук былой точности, отправляется на поиски исцеления, добирается до тайной школы в Катманду и открывает для себя мир магии и параллельных измерений. Фильм известен своими визуально необычными сценами с искривлённым городским пространством.","fact":"Съёмки многих «гнущихся» городских пейзажей вдохновлялись оптическими иллюзиями художника Мауритса Эшера.","wiki_en":"Doctor Strange (2016 film)"},{"name":"Чёрная пантера","emoji":"🐾","meta":["супергероика","2018","Райан Куглер"],"description":"После смерти отца принц Т'Чалла возвращается в технологически передовое, но скрытое от мира африканское королевство Ваканда, чтобы занять престол и защитить страну от внутренних и внешних угроз. Фильм с преимущественно чернокожим актёрским составом стал явлением далеко за пределами кино и первой супергеройской картиной, номинированной на «Оскар» за лучший фильм.","fact":"Художники по костюмам и декорациям опирались на реальные традиции разных африканских культур, создавая вымышленную эстетику Ваканды.","wiki_en":"Black Panther (film)"},{"name":"Человек-муравей","emoji":"🐜","meta":["супергероика","2015","Пейтон Рид"],"description":"Мелкий воришка Скотт Лэнг получает от изобретателя Хэнка Пима костюм, позволяющий уменьшаться до размеров насекомого и управлять армией муравьёв, и должен использовать эту способность, чтобы предотвратить кражу опасной технологии. Фильм добавил во вселенную Marvel непривычный камерный и комедийный тон.","fact":"Идея костюма Человека-муравья появилась в комиксах ещё в 1962 году, задолго до расцвета супергеройских киновселенных.","wiki_en":"Ant-Man (film)"},{"name":"Человек-паук: Через вселенные","emoji":"🕸️","meta":["анимация","2018","Персикетти, Рэмзи, Ротман"],"description":"Подросток Майлз Моралес получает те же способности, что и Питер Паркер, и знакомится с несколькими версиями Человека-паука из параллельных вселенных, которых объединяет общая угроза. Фильм получил «Оскар» как лучшая анимационная картина, а его яркий, вдохновлённый комиксами визуальный стиль изменил представление о супергеройской анимации.","fact":"Художники разработали особую технику анимации, имитирующую частоту смены кадров классических комиксов и печатный растр.","wiki_en":"Spider-Man: Into the Spider-Verse"},{"name":"Веном","emoji":"👅","meta":["супергероика","2018","Рубен Фляйшер"],"description":"Журналист-расследователь Эдди Брок в ходе разоблачения корпорации случайно заражается инопланетным симбиотом, который срастается с его телом и наделяет нечеловеческой силой, требуя взамен подчинения своим хищным инстинктам. Фильм построен на необычном напряжённом взаимодействии человека и агрессивного пришельца внутри одного тела.","fact":"Персонаж Венома впервые появился в комиксах о Человеке-пауке ещё в конце 1980-х как его тёмный антагонист.","wiki_en":"Venom (2018 film)"},{"name":"Хроники Нарнии: Лев, колдунья и волшебный шкаф","emoji":"🦁","meta":["фэнтези","2005","Эндрю Адамсон"],"description":"Четверо детей, эвакуированных из Лондона во время войны, случайно попадают через платяной шкаф в волшебную страну Нарнию, скованную вечной зимой злой Белой колдуньей, и вступают в союз со львом Асланом. Экранизация книги Клайва Льюиса открыла целую серию фильмов о приключениях в Нарнии.","fact":"Съёмки заснеженных пейзажей Нарнии проходили в Новой Зеландии, той же стране, где снимали трилогию «Властелин колец».","wiki_en":"The Chronicles of Narnia: The Lion, the Witch and the Wardrobe"},{"name":"Властелин колец: Две крепости","emoji":"💍","meta":["фэнтези","2002","Питер Джексон"],"description":"Вторая часть трилогии Питера Джексона продолжает историю Братства кольца, разделившегося на несколько групп: Фродо и Сэм пробираются к Мордору с проводником Голлумом, а остальные ввязываются в грандиозную битву за крепость Хельмова Падь. Фильм известен масштабным сражением, ставшим одним из самых впечатляющих в истории кино.","fact":"Персонаж Голлум был создан с помощью технологии захвата движения, которую актёр Энди Серкис во многом помог довести до совершенства.","wiki_en":"The Lord of the Rings: The Two Towers"},{"name":"Властелин колец: Возвращение короля","emoji":"👑","meta":["фэнтези","2003","Питер Джексон"],"description":"Заключительная часть трилогии Питера Джексона сводит воедино все сюжетные линии: армии добра готовятся к решающему сражению у стен Минас Тирита, пока Фродо и Сэм в одиночку продолжают опасный путь к Роковой горе. Фильм получил рекордные одиннадцать «Оскаров», включая награду за лучший фильм.","fact":"Это один из немногих фильмов фэнтезийного жанра, когда-либо получавших «Оскар» за лучший фильм года.","wiki_en":"The Lord of the Rings: The Return of the King"},{"name":"Хоббит: Нежданное путешествие","emoji":"🗝️","meta":["фэнтези","2012","Питер Джексон"],"description":"Спокойный хоббит Бильбо Бэггинс неожиданно для себя присоединяется к отряду гномов, отправившихся отвоёвывать у дракона Смауга свою древнюю родину — Одинокую гору. Первая часть трилогии-приквела к «Властелину колец» вновь перенесла зрителей в Средиземье спустя десятилетие после оригинальной саги.","fact":"Фильм сняли с повышенной частотой кадров — 48 в секунду вместо привычных 24 — и в части кинотеатров показывали именно так, что вызвало споры среди зрителей.","wiki_en":"The Hobbit: An Unexpected Journey"},{"name":"Гарри Поттер и Тайная комната","emoji":"🐍","meta":["фэнтези","2002","Крис Коламбус"],"description":"На втором курсе Хогвартса Гарри и его друзья сталкиваются с загадочными нападениями на учеников и пытаются разгадать тайну легендарной Тайной комнаты, якобы скрытой в стенах школы чародейства. Вторая часть киносерии о юном волшебнике углубила мифологию и мрачность магического мира.","fact":"Именно в этом фильме зрители впервые слышат змеиный язык парселтанг, на котором Гарри неожиданно для всех умеет говорить.","wiki_en":"Harry Potter and the Chamber of Secrets (film)"},{"name":"Гарри Поттер и узник Азкабана","emoji":"🐺","meta":["фэнтези","2004","Альфонсо Куарон"],"description":"В Хогвартс приходит весть о побеге опасного преступника Сириуса Блэка, а школу начинают патрулировать зловещие стражи Азкабана — дементоры, питающиеся человеческими эмоциями. Смена режиссёра придала третьему фильму серии более мрачный и визуально изощрённый стиль по сравнению с предыдущими частями.","fact":"Альфонсо Куарон попросил актёров написать эссе от лица своих персонажей, чтобы глубже понять их внутренний мир перед съёмками.","wiki_en":"Harry Potter and the Prisoner of Azkaban (film)"},{"name":"Гарри Поттер и Кубок огня","emoji":"🔥","meta":["фэнтези","2005","Майк Ньюэлл"],"description":"Хогвартс принимает Турнир трёх волшебников, на который съезжаются ученики других магических школ Европы, но неожиданно в списке участников появляется и имя Гарри Поттера, хотя он не подавал заявку. Четвёртый фильм серии впервые вывел историю за пределы школьных стен на международный магический турнир.","fact":"Майк Ньюэлл стал первым британским режиссёром в серии: до него фильмы о Гарри Поттере снимали американец и мексиканец.","wiki_en":"Harry Potter and the Goblet of Fire (film)"},{"name":"Гарри Поттер и Дары смерти: Часть 2","emoji":"⚡","meta":["фэнтези","2011","Дэвид Йейтс"],"description":"Заключительный фильм киносаги о Гарри Поттере переносит финальную битву между силами добра и Волан-де-Мортом прямо в стены Хогвартса, ставшего полем масштабного сражения. Картина завершила одну из самых кассовых и продолжительных франшиз в истории кино.","fact":"Это самый кассовый фильм серии и единственный из восьми, собравший в мировом прокате больше миллиарда долларов.","wiki_en":"Harry Potter and the Deathly Hallows – Part 2"},{"name":"Фантастические твари и где они обитают","emoji":"🐾","meta":["фэнтези","2016","Дэвид Йейтс"],"description":"Действие спин-оффа о мире Гарри Поттера переносится в Нью-Йорк 1920-х годов, где эксцентричный магозоолог Ньют Саламандер путешествует с чемоданом, полным волшебных существ, и случайно выпускает часть из них на свободу. Фильм основан на одноимённом справочнике, который в книжной вселенной написал сам Ньют.","fact":"Сценарий к фильму впервые в киносерии написала сама Джоан Роулинг, а не сценаристы по мотивам её книг.","wiki_en":"Fantastic Beasts and Where to Find Them (film)"},{"name":"Звёздные войны. Эпизод V: Империя наносит ответный удар","emoji":"❄️","meta":["космическая опера","1980","Ирвин Кершнер"],"description":"Повстанцы отступают на ледяную планету Хот под натиском Империи, а Люк Скайуокер отправляется на болотную планету Дагоба обучаться у мудрого мастера-джедая Йоды, пока его друзья пытаются скрыться от имперской погони. Вторую часть саги критики и фанаты часто называют лучшим фильмом всей франшизы.","fact":"В этом фильме зритель впервые видит магистра Йоду, изначально задуманного как кукольного персонажа, которым управляли кукловоды.","wiki_en":"The Empire Strikes Back"},{"name":"Звёздные войны. Эпизод VI: Возвращение джедая","emoji":"🌲","meta":["космическая опера","1983","Ричард Маркуанд"],"description":"Люк Скайуокер возвращается, чтобы спасти закованного в карбоните Хана Соло, а повстанцы готовят решающий удар по новой Звезде смерти Империи, заручившись неожиданной поддержкой лесных жителей планеты Эндор. Фильм завершил оригинальную трилогию «Звёздных войн».","fact":"Пушистые лесные жители эндорцы, эвоки, были придуманы специально для этого фильма и с тех пор остаются одними из самых узнаваемых существ саги.","wiki_en":"Return of the Jedi"},{"name":"Звёздные войны. Эпизод I: Скрытая угроза","emoji":"🤖","meta":["космическая опера","1999","Джордж Лукас"],"description":"Два рыцаря-джедая отправляются защищать королеву планеты Набу от торговой блокады и по пути находят на пустынной Татуине мальчика-раба Энакина Скайуокера, в котором чувствуют необычайно сильную связь с Силой. Первый фильм приквельной трилогии впервые показал, как начиналась история будущего Дарта Вейдера.","fact":"Джа-Джа Бинкс стал одним из первых полностью компьютерных персонажей, игравших в кадре большую роль наравне с живыми актёрами.","wiki_en":"Star Wars: Episode I – The Phantom Menace"},{"name":"Звёздные войны: Пробуждение силы","emoji":"⚡","meta":["космическая опера","2015","Джей Джей Абрамс"],"description":"Спустя десятилетия после падения Империи новая угроза в лице Первого Ордена нависает над галактикой, а сборщица утиля Рей и бывший штурмовик Финн оказываются втянуты в противостояние, продолжающее историю оригинальной трилогии. Фильм открыл новую эпоху франшизы и вернул на экран классических героев саги.","fact":"Создатели фильма сознательно сделали ставку на практические декорации и настоящих роботов вместо полного перехода на компьютерную графику.","wiki_en":"Star Wars: The Force Awakens"},{"name":"Изгой-один: Звёздные войны. Истории","emoji":"🛰️","meta":["космическая опера","2016","Гарет Эдвардс"],"description":"Группа повстанцев-разведчиков во главе с Джин Эрсо отправляется на опасное задание, чтобы похитить чертежи Звезды смерти незадолго до событий первого фильма франшизы 1977 года. Первый самостоятельный спин-офф «Звёздных войн» рассказывает историю о цене, которую платят безымянные герои ради общей победы.","fact":"Создатели воссоздали облик нескольких персонажей классической трилогии с помощью компьютерной графики, чтобы они появились в кадре молодыми.","wiki_en":"Rogue One"},{"name":"Стартрек","emoji":"🖖","meta":["фантастика","2009","Джей Джей Абрамс"],"description":"Перезапуск легендарной франшизы рассказывает о молодости капитана Джеймса Кирка и мистера Спока, которые встречаются на борту звездолёта «Энтерпрайз» и учатся работать вместе перед лицом угрозы от мстительного пришельца из будущего. Фильм познакомил новое поколение зрителей со вселенной «Звёздного пути».","fact":"Сюжет фильма использует альтернативную временную линию, что позволило создателям переосмыслить классических героев, не нарушая канон прежних сериалов.","wiki_en":"Star Trek (2009 film)","wiki_ru":"Звёздный путь (фильм, 2009)"},{"name":"Чужие","emoji":"👽","meta":["фантастика","1986","Джеймс Кэмерон"],"description":"Спустя десятилетия после встречи с инопланетным хищником уорент-офицер Эллен Рипли отправляется вместе с отрядом космических пехотинцев на колонизированную планету, где пропала связь с поселенцами, и обнаруживает целый рой смертоносных существ. Сиквел культового фильма Ридли Скотта сменил жанр хоррора на военный боевик.","fact":"За роль Рипли Сигурни Уивер получила номинацию на «Оскар» как лучшая актриса — редчайший случай для фантастического боевика.","wiki_en":"Aliens (film)"},{"name":"Терминатор","emoji":"🤖","meta":["фантастика","1984","Джеймс Кэмерон"],"description":"Из будущего в Лос-Анджелес отправляется киборг-убийца, запрограммированный уничтожить женщину по имени Сара Коннор, а следом за ним прибывает солдат, посланный её защитить. Малобюджетный фильм Джеймса Кэмерона стал классикой научной фантастики и сделал Арнольда Шварценеггера мировой звездой.","fact":"Реплика терминатора «Я вернусь» была в сценарии обычной служебной фразой, а стала одной из самых известных цитат в истории кино.","wiki_en":"The Terminator"},{"name":"Терминатор 3: Восстание машин","emoji":"🤖","meta":["фантастика","2003","Джонатан Мостоу"],"description":"Спустя годы после отменённого судного дня повзрослевший Джон Коннор снова оказывается целью нового, более совершенного терминатора-убийцы, а на его защиту приходит очередная модель робота-защитника. Третий фильм франшизы продолжил историю без участия режиссёра-основателя серии Джеймса Кэмерона.","fact":"Главным противником здесь стала Т-Х — первая женская модель терминатора в истории франшизы.","wiki_en":"Terminator 3: Rise of the Machines"},{"name":"Матрица: Перезагрузка","emoji":"💊","meta":["фантастика","2003","Вачовски"],"description":"Нео и его союзники по Зиону продолжают борьбу с машинами, погрузившими человечество в виртуальную реальность, и сталкиваются с новыми откровениями о природе самой Матрицы и своей роли в ней. Второй фильм трилогии расширил философскую и визуальную вселенную оригинала масштабными экшн-сценами.","fact":"Сцена массовой битвы Нео с десятками копий агента Смита потребовала создания технологии цифрового клонирования актёра для сотен дублей.","wiki_en":"The Matrix Reloaded"},{"name":"Матрица: Революция","emoji":"🕶️","meta":["фантастика","2003","Вачовски"],"description":"Заключительная часть трилогии переносит противостояние людей и машин к решающей точке, когда судьба Зиона и всей Матрицы зависит от последних шагов Нео в обоих мирах — реальном и виртуальном. Фильм вышел в прокат спустя всего несколько месяцев после предыдущей части.","fact":"Прокат устроили как глобальное событие: фильм вышел во всём мире практически одновременно, в один и тот же час по всем часовым поясам.","wiki_en":"The Matrix Revolutions"},{"name":"Назад в будущее 2","emoji":"🛹","meta":["фантастика","1989","Роберт Земекис"],"description":"Марти Макфлай и доктор Эмметт Браун отправляются на летающем автомобиле-путешественнике во времени в 2015 год, чтобы предотвратить катастрофу в будущем их семьи, но случайное вмешательство искажает и прошлое, и настоящее. Сиквел прославился футуристическими предсказаниями технологий, часть которых позже действительно появилась.","fact":"Летающий скейтборд ховерборд, показанный в фильме, впоследствии не раз пытались воссоздать инженеры и энтузиасты в реальности.","wiki_en":"Back to the Future Part II"},{"name":"Назад в будущее 3","emoji":"🤠","meta":["фантастика","1990","Роберт Земекис"],"description":"Марти Макфлай отправляется на машине времени в 1885 год на Дикий Запад, чтобы спасти доктора Брауна, застрявшего там и влюбившегося в местную учительницу. Заключительная часть трилогии сменила футуристический антураж на классику вестерна, сохранив фирменный юмор и приключенческий дух серии.","fact":"Вторую и третью части снимали одним производственным блоком почти подряд, и в прокат они вышли с разницей примерно в полгода.","wiki_en":"Back to the Future Part III"},{"name":"Индиана Джонс и Храм судьбы","emoji":"💎","meta":["приключения","1984","Стивен Спилберг"],"description":"Археолог-авантюрист Индиана Джонс попадает в индийскую деревню, где местный культ похищает детей и священный камень, вынуждая героя спуститься в подземный храм, полный смертельных ловушек. Приквел к «Искателям утраченного ковчега» отличается более мрачным и жёстким тоном, чем остальные фильмы серии.","fact":"Именно из-за жёстких сцен этого фильма в американской системе рейтингов позже ввели промежуточную категорию PG-13.","wiki_en":"Indiana Jones and the Temple of Doom"},{"name":"Индиана Джонс и последний крестовый поход","emoji":"🏺","meta":["приключения","1989","Стивен Спилберг"],"description":"Индиана Джонс отправляется на поиски пропавшего отца и легендарного Святого Грааля, соревнуясь с нацистскими агентами, также охотящимися за реликвией. В этой части к герою впервые присоединяется его отец, профессор Генри Джонс, в исполнении Шона Коннери.","fact":"Шон Коннери, сыгравший отца Индианы, на самом деле был старше исполнителя главной роли Харрисона Форда всего на двенадцать лет.","wiki_en":"Indiana Jones and the Last Crusade"},{"name":"Пираты Карибского моря: Сундук мертвеца","emoji":"🐙","meta":["приключения","2006","Гор Вербински"],"description":"Капитан Джек Воробей пытается расплатиться с долгом перед капитаном «Летучего голландца» Дэйви Джонсом, пока Уилл Тёрнер и Элизабет Суонн оказываются втянуты в опасную погоню за легендарным сундуком с сердцем морского владыки. Второй фильм франшизы значительно расширил мифологию проклятых морей.","fact":"Для облика Дэйви Джонса с щупальцами вместо бороды актёру Биллу Найи пришлось сниматься в технологии захвата движения.","wiki_en":"Pirates of the Caribbean: Dead Man's Chest"},{"name":"Пираты Карибского моря: На краю света","emoji":"🏴‍☠️","meta":["приключения","2007","Гор Вербински"],"description":"Пиратские капитаны со всех морей объединяются в Братский совет, чтобы противостоять Ост-Индской торговой компании, стремящейся истребить пиратство раз и навсегда, а друзьям Джека Воробья приходится вызволять его из потустороннего мира. Третий фильм трилогии завершил историю о проклятии «Чёрной жемчужины».","fact":"Для масштабной финальной битвы кораблей у водоворота создатели построили гигантские декорации, вращавшиеся на специальной платформе-гироскопе.","wiki_en":"Pirates of the Caribbean: At World's End"},{"name":"Форсаж","emoji":"🏎️","meta":["боевик","2001","Роб Коэн"],"description":"Полицейский под прикрытием внедряется в сообщество уличных гонщиков Лос-Анджелеса, чтобы расследовать серию ограблений грузовиков, но постепенно сближается с лидером банды и его сестрой. Первый фильм франшизы о нелегальных гонках положил начало одной из самых долгоживущих и кассовых серий в истории кино.","fact":"Бюджет первого фильма был сравнительно скромным, но культ уличных гонок и тюнинга, который он породил, вывел серию в мировые блокбастеры.","wiki_en":"The Fast and the Furious (2001 film)","wiki_ru":"Форсаж (фильм, 2001, США)"},{"name":"Форсаж 7","emoji":"🚗","meta":["боевик","2015","Джеймс Ван"],"description":"Команда уличных гонщиков и бывших преступников вступает в противостояние с наёмным убийцей, мстящим за брата, а действие переносится с американских шоссе на улицы Абу-Даби и горные дороги Кавказа. Фильм стал одним из самых кассовых в истории франшизы.","fact":"Съёмки прервались после гибели Пола Уокера в автокатастрофе: сценарий переписали, а оставшиеся сцены доснимали с братьями актёра и компьютерной графикой.","wiki_en":"Furious 7"},{"name":"Миссия невыполнима 2","emoji":"🕶️","meta":["боевик","2000","Джон Ву"],"description":"Агент Итан Хант отправляется в Сидней, чтобы остановить бывшего коллегу, похитившего смертельно опасный вирус и планирующего продать его вместе с вакциной, обогатившись на искусственной эпидемии. Второй фильм франшизы отличается яркой, почти балетной боевой хореографией режиссёра Джона Ву.","fact":"Многие трюковые сцены, включая скалолазание в начале фильма, Том Круз выполнял лично, без дублёров.","wiki_en":"Mission: Impossible II"},{"name":"Миссия невыполнима: Протокол Фантом","emoji":"🏙️","meta":["боевик","2011","Брэд Бёрд"],"description":"После взрыва в Кремле, в котором обвиняют агентов IMF, организацию расформировывают, и Итан Хант с небольшой командой вынужден действовать в одиночку без поддержки правительства, чтобы предотвратить ядерную угрозу. Фильм прославился эффектной сценой восхождения по самому высокому небоскрёбу мира в Дубае.","fact":"Сцену на небоскрёбе Бурдж-Халифа Том Круз снимал на реальной высоте более четырёхсот метров, с минимумом цифровых эффектов.","wiki_en":"Mission: Impossible – Ghost Protocol"},{"name":"Голдфингер","emoji":"🔫","meta":["боевик","1964","Гай Хэмилтон"],"description":"Агент 007 Джеймс Бонд расследует деятельность золотого магната Голдфингера, который вынашивает дерзкий план радиоактивного заражения золотого запаса Форт-Нокса, чтобы обрушить мировую экономику. Третий фильм бондианы задал канон франшизы — от машины с гаджетами до эффектных злодеев и роковых женщин.","fact":"Именно в этом фильме впервые появился знаменитый автомобиль Бонда Aston Martin DB5, ставший одним из символов франшизы.","wiki_en":"Goldfinger (film)"},{"name":"007: Не время умирать","emoji":"🎯","meta":["боевик","2021","Кэри Дзёдзи Фукунага"],"description":"Вышедший в отставку Джеймс Бонд наслаждается спокойной жизнью на Ямайке, пока старый друг из ЦРУ не просит его помощи в поисках похищенного учёного, чей проект скрывает смертельно опасное оружие. Пятый и заключительный фильм с Дэниелом Крейгом в роли Бонда завершил многолетнюю сюжетную арку персонажа.","fact":"При хронометраже около 163 минут это самый длинный фильм официальной бондианы.","wiki_en":"No Time to Die"},{"name":"Скайфолл","emoji":"🏴","meta":["боевик","2012","Сэм Мендес"],"description":"После провальной операции и ранения Джеймс Бонд возвращается на службу, чтобы выследить бывшего агента МИ-6, ставшего кибертеррористом и угрожающего лично М и всей британской разведке. Фильм вышел к пятидесятилетию франшизы и получил два «Оскара», включая награду за песню.","fact":"Заглавная песня Адель стала первой композицией из бондианы, получившей «Оскар», — прежние темы франшизы доходили лишь до номинаций.","wiki_en":"Skyfall"},{"name":"Умри, но не сейчас","emoji":"❄️","meta":["боевик","2002","Ли Тамахори"],"description":"После долгого плена в Северной Корее Джеймс Бонд возвращается к службе и расследует связь загадочного магната с алмазным бизнесом и разработкой опасного оружия на основе спутниковой технологии. Фильм вышел к сороковой годовщине франшизы и стал последним с Пирсом Броснаном в главной роли.","fact":"Бонду здесь достался автомобиль с адаптивной маскировкой, делающей машину невидимой, — один из самых фантастических гаджетов за всю историю франшизы.","wiki_en":"Die Another Day"},{"name":"Джон Уик 2","emoji":"🐺","meta":["боевик","2017","Чед Стахелски"],"description":"Отставной наёмный убийца Джон Уик вынужден вернуться в мир контрактных убийств из-за старого долга чести перед итальянским криминальным авторитетом, что ставит на кон саму его жизнь по неписаным законам преступного сообщества. Сиквел значительно расширил вымышленную вселенную наёмных убийц из первого фильма.","fact":"Многие сложные боевые сцены актёр Киану Ривз отрабатывал лично на протяжении месяцев интенсивных тренировок перед съёмками.","wiki_en":"John Wick: Chapter 2"},{"name":"Джон Уик 3","emoji":"🐴","meta":["боевик","2019","Чед Стахелски"],"description":"Объявленный вне закона за нарушение священных правил преступного сообщества, Джон Уик спасается бегством по улицам Нью-Йорка, пытаясь найти союзников, пока на его голову назначена огромная награда. Третий фильм серии ещё глубже раскрывает тайную международную организацию наёмных убийц.","fact":"В одной из сцен фильма Джон Уик сражается с противниками, используя в качестве оружия книги из библиотеки — редкий пример импровизированного боя.","wiki_en":"John Wick: Chapter 3 – Parabellum"},{"name":"Русалочка","emoji":"🧜‍♀️","meta":["анимация","1989","Клементс и Маскер"],"description":"Юная русалка Ариэль мечтает жить среди людей и, влюбившись в человеческого принца, заключает опасную сделку с морской колдуньей Урсулой, обменивая голос на пару ног. Мультфильм студии Disney по мотивам сказки Андерсена открыл так называемый «ренессанс» диснеевской анимации конца XX века.","fact":"Песня Under the Sea из этого мультфильма получила «Оскар» и стала одной из самых узнаваемых диснеевских мелодий.","wiki_en":"The Little Mermaid (1989 film)"},{"name":"Красавица и чудовище","emoji":"🌹","meta":["анимация","1991","Труздейл и Уайз"],"description":"Книголюбивая девушка Белль соглашается остаться пленницей в замке заколдованного принца, обращённого в чудовище, чтобы освободить своего отца, и постепенно за грубой внешностью хозяина замка открывает добрую душу. Мультфильм стал первой полнометражной анимационной картиной, номинированной на «Оскар» за лучший фильм.","fact":"Сцену вальса в бальном зале сделали с трёхмерным компьютерным фоном — для рисованной анимации это был тогда настоящий технический прорыв.","wiki_en":"Beauty and the Beast (1991 film)"},{"name":"Аладдин","emoji":"🧞","meta":["анимация","1992","Клементс и Маскер"],"description":"Уличный воришка Аладдин находит волшебную лампу с джинном, способным исполнить три любых желания, и использует их, чтобы завоевать сердце принцессы Жасмин, притворившись принцем. Мультфильм по мотивам сказок «Тысячи и одной ночи» прославился ярким восточным колоритом и харизматичным джинном.","fact":"Роль джинна озвучил комик Робин Уильямс, во многом импровизировавший реплики персонажа прямо в студии звукозаписи.","wiki_en":"Aladdin (1992 Disney film)"},{"name":"Покахонтас","emoji":"🍃","meta":["анимация","1995","Гэбриэл и Голдберг"],"description":"Дочь вождя индейского племени Покахонтас встречает английского колониста капитана Джона Смита и пытается предотвратить конфликт между своим народом и прибывшими поселенцами. Мультфильм Disney основан на легендарной, во многом мифологизированной истории реальной исторической личности XVII века.","fact":"Это первый полнометражный мультфильм студии Disney, главной героиней которого стала персонаж, основанный на реальном историческом человеке.","wiki_en":"Pocahontas (1995 film)"},{"name":"Мулан","emoji":"⚔️","meta":["анимация","1998","Бэнкрофт и Кук"],"description":"Девушка Мулан, переодевшись мужчиной, вместо больного отца отправляется на военную службу в императорскую армию Китая, чтобы защитить страну от вторжения гуннов. Мультфильм Disney основан на древней китайской легенде о деве-воительнице и стал одним из первых диснеевских фильмов с независимой героиней-воином.","fact":"Легенда о Хуа Мулань, на которой основан сюжет, известна в Китае по поэме «Баллада о Мулань», созданной около полутора тысяч лет назад.","wiki_en":"Mulan (1998 film)"},{"name":"Корпорация монстров","emoji":"👹","meta":["анимация","2001","Пит Доктер"],"description":"На фабрике, где монстры пугают детей ради выработки энергии из их криков, добродушный великан Салли и его напарник-циклоп Майк случайно впускают в свой мир маленькую девочку, нарушая все правила монстрячьего общества. Мультфильм студии Pixar остроумно переворачивает классические детские страхи наизнанку.","fact":"Для реалистичной анимации меха Салли пришлось разработать специальную технологию симуляции шерсти, которую позже применяли и в других фильмах Pixar.","wiki_en":"Monsters, Inc."},{"name":"Суперсемейка","emoji":"🦸‍♀️","meta":["анимация","2004","Брэд Бёрд"],"description":"Семья бывших супергероев, вынужденных скрывать свои способности и жить обычной жизнью после запрета героической деятельности, снова берётся за спасение мира, когда против них начинает действовать коварный злодей. Мультфильм Pixar стал одной из первых крупных анимационных картин, всерьёз обыгравших жанр супергероики.","fact":"Это первый полнометражный мультфильм студии Pixar с преимущественно человеческими персонажами вместо игрушек, насекомых или животных.","wiki_en":"The Incredibles"},{"name":"Тачки","emoji":"🏎️","meta":["анимация","2006","Джон Лассетер"],"description":"Высокомерная гоночная машина Молния Маккуин по пути на важные соревнования застревает в маленьком провинциальном городке на легендарной трассе Route 66 и постепенно учится ценить дружбу и уважение вместо личной славы. Мультфильм Pixar происходит в мире, полностью населённом ожившими автомобилями.","fact":"Дизайнеры фильма ездили в настоящие автомобильные туры по исторической трассе Route 66, чтобы точнее передать атмосферу маленьких придорожных городков Америки.","wiki_en":"Cars (film)"},{"name":"Рататуй","emoji":"🐀","meta":["анимация","2007","Брэд Бёрд"],"description":"Крыса Реми с тонким нюхом и мечтой стать шеф-поваром тайно помогает неумелому помощнику повара готовить блюда высокой кухни в престижном парижском ресторане, управляя его действиями из-под колпака. Мультфильм Pixar сочетает гастрономическую тему с трогательной историей о праве на мечту вопреки происхождению.","fact":"Аниматоры студии специально проходили стажировку на профессиональных кухнях, чтобы достоверно изобразить процесс приготовления блюд.","wiki_en":"Ratatouille (film)"},{"name":"Головоломка","emoji":"🧠","meta":["анимация","2015","Пит Доктер"],"description":"Внутри головы девочки Райли живут её персонифицированные эмоции — Радость, Грусть, Гнев, Страх и Брезгливость, — которые пытаются справиться с переездом семьи в новый город и взрослением своей хозяйки. Мультфильм Pixar необычно визуализирует работу человеческой психики и памяти.","fact":"Создатели фильма консультировались с настоящими психологами и нейробиологами, чтобы правдоподобно показать устройство эмоций и памяти.","wiki_en":"Inside Out (2015 film)"},{"name":"Зверополис","emoji":"🦊","meta":["анимация","2016","Ховард и Мур"],"description":"Целеустремлённая крольчиха Джуди Хоппс становится первым кроликом в полиции мегаполиса, где живут только животные, и вынуждена объединиться с хитрым лисом-мошенником, чтобы раскрыть загадочное дело о пропавших горожанах. Мультфильм Disney поднимает темы предрассудков и стереотипов через сатирическую призму звериного мира.","fact":"Художники разработали для каждого района Зверополиса отдельную архитектуру, приспособленную под животных разного размера — от мышей до слонов.","wiki_en":"Zootopia"},{"name":"Моана","emoji":"🌊","meta":["анимация","2016","Клементс и Маскер"],"description":"Дочь вождя полинезийского острова Моана отправляется в опасное океанское путешествие вместе с полубогом Мауи, чтобы вернуть похищенное им сердце богини природы и спасти свой народ от надвигающейся беды. Мультфильм Disney опирается на мифологию и мореходные традиции народов Тихоокеанских островов.","fact":"Создатели фильма несколько лет консультировались с историками, антропологами и мореплавателями Океании, чтобы достоверно передать их культуру.","wiki_en":"Moana (2016 film)"},{"name":"Рапунцель: Запутанная история","emoji":"👱‍♀️","meta":["анимация","2010","Грено и Ховард"],"description":"Девушка с волшебными волосами невероятной длины, много лет запертая колдуньей в высокой башне, впервые покидает своё укрытие с помощью обаятельного разбойника, чтобы увидеть загадочные огни, которые каждый год видит из окна. Диснеевская версия сказки братьев Гримм сочетает классический сюжет с современным юмором.","fact":"На анимацию длинных развевающихся волос Рапунцель у художников студии ушло особенно много времени — они разрабатывали для этого отдельную технологию симуляции.","wiki_en":"Tangled"},{"name":"Ральф","emoji":"🕹️","meta":["анимация","2012","Рич Мур"],"description":"Злодей из старой видеоигры по имени Ральф устаёт от роли антагониста и отправляется путешествовать по другим играм аркадного автомата в поисках медали, которая докажет, что он тоже может быть хорошим. Мультфильм Disney остроумно обыгрывает эстетику и персонажей классических видеоигр разных эпох.","fact":"В фильме в качестве камео появляются узнаваемые персонажи из настоящих видеоигр, включая героев Sonic the Hedgehog и Pac-Man.","wiki_en":"Wreck-It Ralph"},{"name":"Как приручить дракона","emoji":"🐉","meta":["анимация","2010","ДеБлуа и Сандерс"],"description":"Юный викинг Иккинг, живущий в деревне охотников на драконов, вместо того чтобы убить раненого чёрного дракона, тайно приручает его и открывает, что драконы совсем не такие чудовища, какими их считали соплеменники. Мультфильм студии DreamWorks стал одной из самых душевных историй о дружбе человека и мифического существа.","fact":"Создавая Беззубика, аниматоры подсматривали повадки у кошек и других настоящих животных, чтобы дракон казался пластичным и по-звериному живым.","wiki_en":"How to Train Your Dragon (2010 film)","wiki_ru":"Как приручить дракона"},{"name":"Мадагаскар","emoji":"🦒","meta":["анимация","2005","Дарнелл и Макграт"],"description":"Четверо животных из нью-йоркского зоопарка — лев, зебра, жираф и бегемотиха — случайно оказываются на диком острове Мадагаскар и учатся выживать без привычного комфорта вольера. Мультфильм студии DreamWorks запомнился яркими персонажами и стал началом популярной анимационной франшизы.","fact":"Отдельные персонажи фильма, особенно неугомонные пингвины, оказались настолько популярны у зрителей, что позже получили собственные сериалы и спин-оффы.","wiki_en":"Madagascar (2005 film)"},{"name":"Кунг-фу Панда","emoji":"🐼","meta":["анимация","2008","Осборн и Стивенсон"],"description":"Неуклюжий и ленивый панда По, работающий в лапшичной своего отца, неожиданно для всех оказывается избран легендарным Воином дракона и должен под руководством строгого мастера освоить боевые искусства, чтобы защитить долину от опасного злодея. Мультфильм DreamWorks соединяет комедию с эстетикой классического кино о кунг-фу.","fact":"Создатели фильма консультировались с настоящими мастерами боевых искусств, чтобы движения анимированных персонажей выглядели технически достоверно.","wiki_en":"Kung Fu Panda (film)","wiki_ru":"Кунг-фу панда"},{"name":"Кошмар перед Рождеством","emoji":"🎃","meta":["анимация","1993","Генри Селик"],"description":"Король Хэллоуина Джек Скеллингтон, уставший год за годом пугать людей, случайно обнаруживает волшебный портал в мир Рождества и решает устроить праздник по-своему, перепутав жуткие традиции с добрыми. Кукольный мультфильм, спродюсированный Тимом Бёртоном, стал культовой классикой на стыке двух праздников.","fact":"Фильм целиком снят покадровой кукольной анимацией, а для мимики Джека Скеллингтона изготовили несколько сотен сменных голов.","wiki_en":"The Nightmare Before Christmas"},{"name":"Ледниковый период","emoji":"🐿️","meta":["анимация","2002","Крис Уэдж"],"description":"Мамонт, ленивец и саблезубый тигр из ледниковой эпохи, изначально не доверяющие друг другу, объединяются, чтобы вернуть человеческого детёныша его племени, и постепенно становятся необычной, но крепкой семьёй. Мультфильм студии Blue Sky Studios положил начало долгоиграющей комедийной франшизе.","fact":"Второстепенный персонаж — белка Скрэт, вечно гоняющаяся за жёлудем, — не произносит ни единого слова, но превратилась в один из главных символов франшизы.","wiki_en":"Ice Age (2002 film)"},{"name":"Гадкий я","emoji":"🍌","meta":["анимация","2010","Коффин и Рено"],"description":"Злодей-неудачник Грю вынашивает план похитить Луну и усыновляет трёх сирот, чтобы использовать их в своей коварной схеме, но неожиданно для себя искренне привязывается к девочкам. Мультфильм студии Illumination познакомил зрителей с миниатюрными жёлтыми помощниками-миньонами, ставшими самостоятельным поп-феноменом.","fact":"Миньоны, задуманные как второстепенные персонажи фильма, впоследствии получили собственную кинофраншизу, ставшую даже более кассовой, чем оригинал.","wiki_en":"Despicable Me (film)"},{"name":"Простоквашино","emoji":"🐱","meta":["анимация","1978","Владимир Попов"],"description":"Мальчик по прозвищу дядя Фёдор уходит жить в деревенский дом в селе Простоквашино вместе с говорящим котом Матроскиным и добродушным псом Шариком, где они заводят хозяйство и переживают забавные бытовые истории. Советский мультфильм по повести Эдуарда Успенского стал одной из самых любимых семейных классик отечественной анимации.","fact":"Фраза кота Матроскина «Чтобы продать что-нибудь ненужное, надо сначала купить что-нибудь ненужное» давно стала расхожей житейской поговоркой.","wiki_en":"Three from Prostokvashino","wiki_ru":"Трое из Простоквашино"},{"name":"Винни-Пух","emoji":"🍯","meta":["анимация","1969","Фёдор Хитрук"],"description":"Первый из советских мультфильмов о плюшевом медвежонке с опилками в голове, который вместе с приятелем Пятачком отправляется за мёдом к пчёлам, притворившись тучкой. Мультфильм Фёдора Хитрука по мотивам сказки Алана Милна создал самобытный, узнаваемый образ Винни-Пуха, отличный от диснеевской версии.","fact":"Голос Винни-Пуха озвучил Евгений Леонов, чей характерный тембр стал неотделим от образа медвежонка для нескольких поколений зрителей.","wiki_en":"Winnie-the-Pooh (1969 film)","wiki_ru":"Винни-Пух (мультфильм)"},{"name":"Ёжик в тумане","emoji":"🦔","meta":["анимация","1975","Юрий Норштейн"],"description":"Маленький ёжик идёт в гости к своему другу Медвежонку считать звёзды, но по пути сбивается с дороги в густом тумане, где сталкивается с загадочными и пугающими образами. Мультфильм Юрия Норштейна неоднократно признавался критиками одним из лучших анимационных фильмов всех времён за свою поэтичную атмосферу.","fact":"Для создания густой туманной атмосферы аниматоры использовали многоярусную технику съёмки с несколькими слоями полупрозрачной кальки.","wiki_en":"Hedgehog in the Fog"},{"name":"Жил-был Пёс","emoji":"🐺","meta":["анимация","1982","Эдуард Назаров"],"description":"Постаревший и изгнанный хозяевами пёс встречает в лесу волка, который вместо того, чтобы съесть его, предлагает неожиданный план спасения, положивший начало необычной дружбе. Короткий мультфильм по мотивам украинской народной сказки известен лаконичным юмором и стал источником множества крылатых фраз.","fact":"Фраза волка «Щас спою» из этого мультфильма давно превратилась в самостоятельную устойчивую шутку в разговорной речи.","wiki_en":"Once Upon a Dog"},{"name":"Бременские музыканты","emoji":"🎸","meta":["анимация","1969","Инесса Ковалевская"],"description":"Компания бродячих зверей-музыкантов во главе с обаятельным Трубадуром отправляется странствовать по дорогам сказочного королевства и помогает Принцессе освободиться от власти деспотичного короля. Советский музыкальный мультфильм по мотивам сказки братьев Гримм прославился яркими песнями в стиле рок-н-ролла.","fact":"Почти все песни в мультфильме спел один человек — Олег Анофриев, озвучивший и Трубадура, и большинство других персонажей.","wiki_en":"The Bremen Town Musicians (1969 film)","wiki_ru":"Бременские музыканты (мультфильм)"},{"name":"Летучий корабль","emoji":"⛵","meta":["анимация","1979","Гарри Бардин"],"description":"Бедный, но находчивый деревенский парень Иван вместе с компанией сказочных помощников строит волшебный летучий корабль, чтобы добиться руки царской дочери вопреки козням хвастливого Полкана. Мультфильм по мотивам русской народной сказки запомнился яркими музыкальными номерами, которые давно живут отдельно от него.","fact":"Песню Бабок-Ёжек из этого мультфильма до сих пор нередко исполняют на детских утренниках как узнаваемый комический номер.","wiki_en":"The Flying Ship (animated film)","wiki_ru":"Летучий корабль (мультфильм)"},{"name":"Снежная королева","emoji":"❄️","meta":["анимация","1957","Лев Атаманов"],"description":"Девочка Герда отправляется в опасное путешествие через холодные северные земли, чтобы найти и спасти своего друга Кая, чьё сердце заморозила коварная Снежная королева. Классическая советская экранизация сказки Ганса Христиана Андерсена признана одной из вершин отечественной рисованной анимации.","fact":"Этот мультфильм произвёл огромное впечатление на японского аниматора Хаяо Миядзаки, который впоследствии называл его одним из источников своего вдохновения.","wiki_en":"The Snow Queen (1957 film)"},{"name":"Двенадцать месяцев","emoji":"🔥","meta":["анимация","1956","Иванов-Вано, Ботов"],"description":"Капризная маленькая королева требует зимой принести ей подснежники, и падчерица мачехи отправляется в морозный лес, где встречает волшебное собрание всех двенадцати месяцев года у костра. Мультфильм по пьесе Самуила Маршака стал одной из самых узнаваемых новогодних сказок советской анимации.","fact":"Каждый из двенадцати месяцев в мультфильме получил собственный узнаваемый визуальный образ и характер в соответствии со своим временем года.","wiki_en":"The Twelve Months (1956 film)","wiki_ru":"Двенадцать месяцев (мультфильм)"},{"name":"Чебурашка","emoji":"🐵","meta":["анимация","1971","Роман Качанов"],"description":"Загадочный неизвестный науке зверёк с большими ушами, найденный в ящике с апельсинами, вместе с крокодилом Геной ищет друзей, помогает окружающим и противостоит козням вредной старушки Шапокляк. Кукольный мультфильм по книгам Эдуарда Успенского сделал Чебурашку одним из самых узнаваемых персонажей советской культуры.","fact":"Образ Чебурашки настолько прижился в массовой культуре, что позже стал официальным талисманом сборной России на нескольких Олимпийских играх.","wiki_en":"Cheburashka (1971 film)","wiki_ru":"Чебурашка (мультфильм, 1971)"},{"name":"Кин-дза-дза!","emoji":"🛸","meta":["фантастика","1986","Георгий Данелия"],"description":"Обычный прораб и случайно оказавшийся рядом студент из-за загадочного устройства инопланетянина переносятся на пустынную планету Плюк в другой галактике, где им приходится осваивать чуждые и абсурдные социальные правила. Сатирическая фантастическая притча Георгия Данелии высмеивает общественные иерархии через вымышленный инопланетный мир.","fact":"Придуманное для фильма слово «ку», заменяющее в языке планеты Плюк едва ли не все выражения, стало устойчивым крылатым выражением в русском языке.","wiki_en":"Kin-dza-dza!"},{"name":"Собачье сердце","emoji":"🐕","meta":["трагикомедия","1988","Владимир Бортко"],"description":"Профессор Преображенский пересаживает бездомному псу Шарику гипофиз человека, в результате чего пёс постепенно превращается в грубого и наглого человека по фамилии Шариков, доставляющего профессору всё больше проблем. Экранизация повести Михаила Булгакова считается одной из лучших телевизионных постановок советского кино.","fact":"Фраза профессора Преображенского «Разруха не в клозетах, а в головах» давно стала самостоятельной цитатой, используемой вне контекста фильма.","wiki_en":"Heart of a Dog (1988 film)","wiki_ru":"Собачье сердце (фильм, 1988)"},{"name":"В бой идут одни старики","emoji":"✈️","meta":["военная драма","1973","Леонид Быков"],"description":"Опытный лётчик-истребитель по прозвищу Маэстро собирает эскадрилью из необстрелянных новичков и превращает её в знаменитую «поющую», стараясь сохранить в ребятах человечность посреди войны. Фильм Леонида Быкова, сыгравшего и главную роль, стал одним из самых любимых советских фильмов о лётчиках.","fact":"Леонид Быков был страстным поклонником авиации и сам выступил не только режиссёром и исполнителем главной роли, но и соавтором сценария фильма.","wiki_en":"Only \"Old Men\" Are Going Into Battle","wiki_ru":"В бой идут одни «старики»"},{"name":"Офицеры","emoji":"🎖️","meta":["военная драма","1971","Владимир Роговой"],"description":"Фильм прослеживает судьбу двух друзей-офицеров и любимой ими женщины на протяжении нескольких десятилетий советской истории — от Гражданской войны до Великой Отечественной, — показывая, как офицерская честь и дружба переживают все испытания. Картина стала эталонным фильмом о преемственности военных поколений.","fact":"Фраза «Есть такая профессия — Родину защищать» из этого фильма стала одной из самых известных цитат советского кино.","wiki_en":"Officers (film)","wiki_ru":"Офицеры (фильм)"},{"name":"А зори здесь тихие","emoji":"🌲","meta":["военная драма","1972","Станислав Ростоцкий"],"description":"Старшина небольшого зенитного поста отправляется с отрядом девушек-зенитчиц в карельские леса выслеживать группу немецких диверсантов, и хрупкий женский отряд принимает неравный бой с врагом. Экранизация повести Бориса Васильева стала одним из самых пронзительных фильмов о женщинах на войне.","fact":"Фильм получил широкое международное признание и был номинирован на «Оскар» как лучший фильм на иностранном языке.","wiki_en":"The Dawns Here Are Quiet (1972 film)","wiki_ru":"А зори здесь тихие (фильм, 1972)"},{"name":"Судьба человека","emoji":"🎖️","meta":["военная драма","1959","Сергей Бондарчук"],"description":"Бывший фронтовик Андрей Соколов рассказывает случайному попутчику историю своей жизни — плен, потерю семьи и обретение нового смысла существования после войны. Режиссёрский дебют Сергея Бондарчука по рассказу Михаила Шолохова стал одним из первых советских фильмов, честно показавших трагедию военнопленных.","fact":"Сергей Бондарчук не только поставил фильм, но и сыграл в нём главную роль, воплотив на экране образ, ставший символом народной стойкости.","wiki_en":"Destiny of a Man","wiki_ru":"Судьба человека (фильм)"},{"name":"Летят журавли","emoji":"🕊️","meta":["военная драма","1957","Михаил Калатозов"],"description":"Влюблённая пара расстаётся, когда юноша уходит добровольцем на фронт, а оставшейся в тылу девушке приходится пережить бомбёжки, потери и трудный моральный выбор в условиях войны. Фильм Михаила Калатозова остаётся единственной советской картиной, удостоенной главного приза Каннского кинофестиваля.","fact":"Оператор Сергей Урусевский снял несколько сцен фильма новаторскими для своего времени методами, включая длинные динамичные проходы камеры без остановки.","wiki_en":"The Cranes Are Flying"},{"name":"Баллада о солдате","emoji":"🎗️","meta":["военная драма","1959","Григорий Чухрай"],"description":"Молодой солдат получает короткий отпуск за подбитый вражеский танк и отправляется навестить мать, но по дороге домой встречает разных людей и помогает им, так что на саму встречу с матерью у него остаются считаные минуты. Простая и трогательная история стала классикой советского кино о войне.","fact":"Фильм получил специальный приз Каннского кинофестиваля и был номинирован на «Оскар» за лучший оригинальный сценарий.","wiki_en":"Ballad of a Soldier"},{"name":"Иваново детство","emoji":"🌒","meta":["военная драма","1962","Андрей Тарковский"],"description":"Мальчик Иван, потерявший семью во время войны, становится юным разведчиком и снова и снова уходит через линию фронта, несмотря на попытки старших офицеров уберечь его от опасности. Полнометражный дебют Андрея Тарковского получил «Золотого льва» Венецианского кинофестиваля.","fact":"Тарковский пришёл на проект уже после того, как съёмки начал другой режиссёр, и практически полностью переснял фильм заново по собственному видению.","wiki_en":"Ivan's Childhood"},{"name":"Андрей Рублёв","emoji":"🎨","meta":["историческая драма","1966","Андрей Тарковский"],"description":"Фильм в нескольких новеллах прослеживает жизнь и духовные искания средневекового иконописца Андрея Рублёва на фоне жестоких княжеских междоусобиц и татарских набегов Древней Руси. Масштабная и философская картина Андрея Тарковского считается одним из вершинных достижений мирового кинематографа.","fact":"Из-за сложной цензурной судьбы полная авторская версия фильма добралась до широкого советского проката лишь спустя несколько лет после завершения съёмок.","wiki_en":"Andrei Rublev (film)"},{"name":"Зеркало","emoji":"🪞","meta":["драма","1975","Андрей Тарковский"],"description":"Автобиографичная и подчёркнуто нелинейная картина Андрея Тарковского соединяет воспоминания о детстве, снах и исторических потрясениях XX века в единый поэтический поток образов вместо привычного сюжета. Фильм считается одним из самых личных и формально смелых произведений режиссёра.","fact":"Роли матери героя в разном возрасте и его жены сыграла одна и та же актриса, что усиливает ощущение переплетения времён в фильме.","wiki_en":"Mirror (1975 film)"},{"name":"Солярис","emoji":"🪐","meta":["фантастика","1972","Андрей Тарковский"],"description":"Психолог отправляется на орбитальную станцию над загадочной планетой-океаном Солярис, где экипаж сталкивается с необъяснимыми видениями, материализующими их глубочайшие воспоминания и чувства вины. Философская экранизация романа Станислава Лема Андреем Тарковским больше сосредоточена на внутреннем мире героев, чем на технологиях будущего.","fact":"Тарковский сознательно уменьшил в фильме количество футуристических декораций и технических деталей, чтобы сместить акцент с фантастики на человеческую драму.","wiki_en":"Solaris (1972 film)"},{"name":"Асса","emoji":"🎸","meta":["драма","1987","Сергей Соловьёв"],"description":"Юная героиня, приехавшая в зимнюю Ялту вместе с криминальным авторитетом Крымовым, влюбляется в чудаковатого молодого музыканта Бананана, и их история разворачивается на фоне пробуждающейся рок-культуры перестроечного времени. Фильм Сергея Соловьёва стал знаковой картиной эпохи перемен конца 1980-х годов.","fact":"В фильме звучат песни группы «Кино», а в финале появляется сам Виктор Цой, исполняющий культовую композицию «Перемен».","wiki_en":"Assa (film)"},{"name":"Игла","emoji":"💉","meta":["драма","1988","Рашид Нугманов"],"description":"Молодой человек по прозвищу Моро возвращается в родной город и пытается вырвать бывшую девушку из наркотической зависимости, вступая в конфликт с теми, кто наживается на её беде. Один из символов казахской новой волны кино стал культовым во многом благодаря главной роли Виктора Цоя.","fact":"Часть фильма снимали на высохшем Аральском море, и кадры с брошенными судами посреди песка стали одним из самых запоминающихся образов картины.","wiki_en":"The Needle (1988 film)"},{"name":"Ирония судьбы. Продолжение","emoji":"🥂","meta":["романтическая комедия","2007","Тимур Бекмамбетов"],"description":"Спустя три десятилетия после новогодних событий классического фильма дети главных героев случайно повторяют судьбу своих родителей, оказавшись втянуты в похожую новогоднюю путаницу в современной Москве. Сиквел культовой советской комедии перенёс знакомый сюжет в реалии XXI века.","fact":"В сиквеле вновь появились актёры оригинальной картины, сыгравшие постаревшие версии своих персонажей.","wiki_en":"Irony of Fate 2","wiki_ru":"Ирония судьбы. Продолжение"},{"name":"Гараж","emoji":"🚗","meta":["трагикомедия","1979","Эльдар Рязанов"],"description":"Собрание кооператива, распределяющего места под гаражи, превращается в затяжной ночной конфликт, где интеллигентные с виду сотрудники научного института обнажают всю подноготную мелких компромиссов и лицемерия. Сатирическая комедия Эльдара Рязанова почти целиком разворачивается в одном помещении.","fact":"Сам Эльдар Рязанов сыграл в фильме безмолвного сотрудника института, который почти всё бурное собрание мирно спит на чучеле животного.","wiki_en":"The Garage (1980 film)","wiki_ru":"Гараж (фильм)"},{"name":"Осенний марафон","emoji":"🍂","meta":["трагикомедия","1979","Георгий Данелия"],"description":"Мягкий и нерешительный переводчик мечется между женой, любовницей и бесконечными чужими просьбами, не находя в себе сил ни одну из них отвергнуть, и постепенно превращает собственную доброту в источник всеобщего страдания. Фильм Георгия Данелии тонко сочетает комедию с настоящей житейской драмой.","fact":"Реплика «Хорошо сидим!» из этого фильма давно разошлась на цитаты и живёт отдельно от него.","wiki_en":"Autumn Marathon"},{"name":"Вокзал для двоих","emoji":"🚉","meta":["мелодрама","1982","Эльдар Рязанов"],"description":"Столичный пианист, которому предстоит суд за то, чего он не совершал, опаздывает на поезд и знакомится с буфетчицей провинциального вокзала, и между ними завязываются непростые, но искренние отношения. Мелодрама Эльдара Рязанова сочетает лиричность с острой социальной сатирой на советский быт.","fact":"Роль буфетчицы стала одной из самых знаковых работ Людмилы Гурченко, объединившей в этом образе комедию и драму.","wiki_en":"Station for Two"},{"name":"Мимино","emoji":"🚁","meta":["трагикомедия","1977","Георгий Данелия"],"description":"Грузинский лётчик, летающий на маленьком вертолёте по горным сёлам, мечтает пересесть за штурвал больших самолётов и отправляется покорять Москву, где неожиданно сближается с армянским шофёром-дальнобойщиком. Тёплая комедия Георгия Данелии о дружбе народов стала одной из самых любимых советских картин.","fact":"Реплика Рубика «Я так думаю!» стала настолько крылатой, что её узнают даже те, кто не видел сам фильм.","wiki_en":"Mimino","wiki_ru":"Мимино"},{"name":"Афоня","emoji":"🔧","meta":["трагикомедия","1975","Георгий Данелия"],"description":"Слесарь-сантехник по прозвищу Афоня ведёт разгульную холостяцкую жизнь, халтурит на вызовах и пропивает деньги, пока цепь случайных встреч не заставляет его задуматься о собственном одиночестве и пустоте такого существования. Комедия Георгия Данелии сочетает бытовой юмор с грустной моралью.","fact":"Роль Афони стала одной из самых узнаваемых в карьере Леонида Куравлёва, много снимавшегося в советских комедиях того времени.","wiki_en":"Afonya","wiki_ru":"Афоня"},{"name":"Экипаж","emoji":"🛫","meta":["катастрофа","1979","Александр Митта"],"description":"Трое членов экипажа гражданского авиалайнера с очень разными характерами и личными проблемами оказываются перед лицом настоящей катастрофы, когда в далёком городе, куда они прилетели за пострадавшими, начинается разрушительное землетрясение. Один из первых советских фильмов-катастроф сочетает бытовую драму с эффектными трюками.","fact":"Для сцен с повреждённым самолётом использовали настоящий списанный авиалайнер, а не только макеты и декорации.","wiki_en":"Air Crew","wiki_ru":"Экипаж (фильм, 1979)"},{"name":"Пираты XX века","emoji":"🏴‍☠️","meta":["боевик","1979","Борис Дуров"],"description":"Экипаж советского торгового судна подвергается нападению современных пиратов-контрабандистов, охотящихся за грузом опиума, и морякам приходится вступить в схватку с хорошо вооружёнными бандитами. Одним из первых советских боевиков с элементами восточных единоборств картина произвела на зрителей эффект разорвавшейся бомбы.","fact":"Фильм стал одним из самых кассовых в истории советского кинопроката, во многом благодаря непривычным для того времени сценам рукопашного боя.","wiki_en":"Pirates of the 20th Century","wiki_ru":"Пираты XX века"},{"name":"Человек-амфибия","emoji":"🐟","meta":["фантастика","1961","Казанский, Чеботарёв"],"description":"Юноша Ихтиандр, которому в детстве пересадили жабры акулы, способен свободно жить как на суше, так и под водой, но влюбляется в обычную девушку, что вынуждает его выбирать между двумя мирами. Экранизация романа Александра Беляева стала одним из первых советских фильмов с масштабными подводными съёмками.","fact":"Подводные сцены снимали в Чёрном море без современного водолазного снаряжения, что было по-настоящему рискованным предприятием для актёров.","wiki_en":"Amphibian Man (film)","wiki_ru":"Человек-амфибия (фильм)"},{"name":"Приключения Электроника","emoji":"🤖","meta":["фантастика","1979","Константин Бромберг"],"description":"Учёный создаёт робота-школьника Электроника, внешне неотличимого от настоящего мальчика Сергея Сыроежкина, и когда робот сбегает из лаборатории, начинается череда путаниц и приключений с их двойниками. Советский телефильм по повести Евгения Велтистова стал одной из любимых детских картин своего времени.","fact":"Песня «Крылатые качели» из этого фильма стала одной из самых узнаваемых детских песен советской эпохи.","wiki_en":"The Adventures of Elektronik","wiki_ru":"Приключения Электроника"},{"name":"Двенадцать стульев","emoji":"🪑","meta":["комедия","1971","Леонид Гайдай"],"description":"Бывший дворянин Ипполит Воробьянинов вместе с ловким авантюристом Остапом Бендером отправляется на поиски фамильных бриллиантов, спрятанных в одном из двенадцати стульев гарнитура, распроданных по всей стране после революции. Экранизация романа Ильфа и Петрова стала одной из самых известных советских комедий об Остапе Бендере.","fact":"Роль Остапа Бендера в этой экранизации сыграл Арчил Гомиашвили, хотя позже свои версии того же персонажа воплощали и другие известные актёры.","wiki_en":"The Twelve Chairs (1971 film)"},{"name":"Не может быть!","emoji":"🎭","meta":["комедия","1975","Леонид Гайдай"],"description":"Фильм состоит из трёх отдельных комедийных новелл по ранним юмористическим произведениям Михаила Зощенко, в которых незадачливые советские граждане попадают в нелепые и забавные бытовые ситуации из-за собственной хитрости или жадности. Леонид Гайдай снова собрал звёздный актёрский состав для этой альманахной комедии.","fact":"Все три истории разворачиваются в антураже нэповских 1920-х — той самой эпохи, о которой писал Зощенко.","wiki_en":"It Can't Be!","wiki_ru":"Не может быть! (фильм)"},{"name":"Спортлото-82","emoji":"🎟️","meta":["комедия","1982","Леонид Гайдай"],"description":"Отдыхающий на черноморском курорте молодой человек теряет лотерейный билет с крупным выигрышем и вместе с новой знакомой пускается на его поиски, а по следу того же билета идёт пронырливый спекулянт. Одна из поздних комедий Леонида Гайдая сохранила фирменный динамичный юмор режиссёра.","fact":"Название отсылает к реальной советской лотерее «Спортлото», билеты которой тогда покупали по всей стране.","wiki_en":"Sportloto-82","wiki_ru":"Спортлото-82"},{"name":"Покровские ворота","emoji":"🏙️","meta":["комедия","1982","Михаил Козаков"],"description":"Действие тёплой ностальгической комедии разворачивается в коммунальной квартире московского района Покровские Ворота середины 1950-х годов, где переплетаются судьбы нескольких колоритных соседей и их романтических историй. Телефильм Михаила Козакова стал одной из самых любимых и часто пересматриваемых советских комедий.","fact":"Несмотря на скромный успех при первом телепоказе, фильм со временем приобрёл культовый статус и стал регулярно транслироваться по телевидению.","wiki_en":"Pokrovsky Gates","wiki_ru":"Покровские ворота (фильм)"},{"name":"Формула любви","emoji":"🪄","meta":["комедия","1984","Марк Захаров"],"description":"В русскую провинциальную усадьбу конца XVIII века приезжает загадочный граф Калиостро, обладающий, по слухам, магическими способностями и формулой вечной молодости, чем немедленно пользуется местное дворянство в собственных корыстных целях. Ироничная костюмированная комедия Марка Захарова обыгрывает легенды об известном авантюристе.","fact":"Реплика «Хочешь большой, но чистой любви?» из этого фильма давно стала самостоятельным ироничным присловьем.","wiki_en":"The Formula of Love","wiki_ru":"Формула любви"},{"name":"Тот самый Мюнхгаузен","emoji":"🎈","meta":["комедия","1979","Марк Захаров"],"description":"Легендарный барон Мюнхгаузен пытается убедить чопорное немецкое общество в правдивости своих невероятных приключений, но сталкивается с бюрократическим требованием официально доказать собственную идентичность через привычные обществу процедуры. Философская комедия Марка Захарова превращает сказочный сюжет в притчу о конформизме.","fact":"Фраза Мюнхгаузена «Улыбайтесь, господа, улыбайтесь» стала одной из самых цитируемых реплик советского телевизионного кино.","wiki_en":"The Very Same Munchhausen","wiki_ru":"Тот самый Мюнхгаузен"},{"name":"Обыкновенное чудо","emoji":"🐻","meta":["сказка","1978","Марк Захаров"],"description":"Волшебник, живущий вдали от людей, превращает медведя в прекрасного юношу, но предупреждает, что тот вновь обратится зверем, если его поцелует влюблённая в него принцесса, и наблюдает, как разворачивается эта сказочная любовная история. Экранизация пьесы Евгения Шварца сочетает романтику с философскими размышлениями о природе любви.","fact":"Музыку к фильму написал Геннадий Гладков, а стихи песен — Юлий Ким, которому тогда приходилось печататься под псевдонимом.","wiki_en":"An Ordinary Miracle (1978 film)","wiki_ru":"Обыкновенное чудо (фильм, 1978)"},{"name":"Здравствуйте, я ваша тётя!","emoji":"👒","meta":["комедия","1975","Виктор Титов"],"description":"Бродяга Бабс Баберлей, случайно попавший в дом оксфордских студентов, соглашается изобразить их богатую тётушку из Бразилии, «где в лесах много-много диких обезьян», и эта маленькая ложь стремительно обрастает лавиной комических недоразумений. Экранизация классической английской комедийной пьесы стала одной из самых пересматриваемых советских комедий.","fact":"Главную роль сыграл Александр Калягин, чья способность к эксцентричной пластике сделала этот образ одним из самых запоминающихся в его карьере.","wiki_en":"Hello, I'm Your Aunt!","wiki_ru":"Здравствуйте, я ваша тётя!"},{"name":"Морозко","emoji":"❄️","meta":["сказка","1964","Александр Роу"],"description":"Капризную мачехину дочь и добрую сироту Настеньку судьба сводит с суровым духом зимнего леса Морозко, который испытывает каждую из них на доброту и трудолюбие, прежде чем наградить или наказать по заслугам. Классическая советская киносказка Александра Роу давно стала неизменным новогодним фильмом для нескольких поколений зрителей.","fact":"В США фильм вышел под названием Jack Frost и позже стал объектом добродушных издёвок в культовом телешоу о странном кино.","wiki_en":"Jack Frost (1964 film)","wiki_ru":"Морозко (фильм, 1964)"},{"name":"Приключения Буратино","emoji":"🪵","meta":["музыкальная сказка","1975","Леонид Нечаев"],"description":"Деревянный человечек Буратино, вырезанный папой Карло из полена, отправляется в школу, но по дороге поддаётся соблазнам кота Базилио и лисы Алисы и попадает в череду опасных и забавных приключений в поисках золотого ключика. Советский музыкальный телефильм по сказке Алексея Толстого стал классикой детского кино.","fact":"Песни из этого фильма, включая знаменитую «Буратино», давно вошли в репертуар детских утренников по всей стране.","wiki_en":"The Adventures of Buratino (1975 film)","wiki_ru":"Приключения Буратино (фильм)"},{"name":"Чучело","emoji":"🎒","meta":["драма","1983","Ролан Быков"],"description":"Новенькая девочка в школьном классе берёт на себя чужую вину и становится объектом жестокой травли со стороны одноклассников, вынужденная пройти через это испытание в одиночку. Один из первых советских фильмов, откровенно показавших школьный буллинг, вызвал широкий общественный резонанс при выходе.","fact":"Главную роль сыграла двенадцатилетняя Кристина Орбакайте, для которой этот фильм стал дебютом в кино.","wiki_en":"Scarecrow (1984 film)","wiki_ru":"Чучело (фильм)"},{"name":"Курьер","emoji":"📮","meta":["трагикомедия","1986","Карен Шахназаров"],"description":"Выпускник школы, не поступивший в институт, устраивается курьером в редакцию журнала и своим ироничным, слегка дерзким поведением ставит в тупик взрослых, привыкших к иным правилам игры. Фильм Карена Шахназарова тонко передал настроение советской молодёжи эпохи перестройки.","fact":"Главную роль исполнил актёр Фёдор Дунаевский, для которого эта работа стала одной из самых заметных в его недолгой кинокарьере.","wiki_en":"Courier (film)","wiki_ru":"Курьер (фильм, 1986)"},{"name":"Маленькая Вера","emoji":"🏭","meta":["драма","1988","Василий Пичул"],"description":"Девушка из семьи заводских рабочих провинциального промышленного города пытается вырваться из давящей бытовой рутины и конфликтов с родителями через отношения с молодым человеком. Фильм Василия Пичула стал одной из первых советских картин, открыто заговоривших о проблемах и интимной жизни молодёжи позднего СССР.","fact":"Съёмки шли в Жданове — сегодняшнем Мариуполе, — и заводские окраины города стали для фильма почти отдельным персонажем.","wiki_en":"Little Vera"},{"name":"Вий","emoji":"👹","meta":["ужасы","1967","Ершов, Кропачёв"],"description":"Молодой семинарист, случайно ставший причиной смерти ведьмы, обязан три ночи подряд читать над её гробом в старой церкви, и с каждой ночью потусторонние силы становятся всё настойчивее. Экранизация повести Николая Гоголя считается первым полнометражным фильмом ужасов, снятым в Советском Союзе.","fact":"Для создания образа монстра Вия и других потусторонних существ съёмочная группа применяла сложный для своего времени грим и механические конструкции.","wiki_en":"Viy (1967 film)"},{"name":"Ночной дозор","emoji":"🌙","meta":["фэнтези","2004","Тимур Бекмамбетов"],"description":"В современной Москве идёт скрытая от обычных людей многовековая борьба между силами Света и Тьмы, а москвич Антон, узнавший в себе способности Иного, оказывается в самом центре этого противостояния на стороне Света. Экранизация романа Сергея Лукьяненко стала одним из первых российских блокбастеров с масштабными спецэффектами.","fact":"Фильм установил рекорд кассовых сборов среди российских картин на момент своего выхода, опередив многие голливудские релизы того года.","wiki_en":"Night Watch (2004 film)"},{"name":"Дневной дозор","emoji":"☀️","meta":["фэнтези","2006","Тимур Бекмамбетов"],"description":"Продолжение истории о войне Света и Тьмы в Москве переносит противостояние Иных на новый уровень, когда в игру вступает древний артефакт, способный переписать саму судьбу мира. Сиквел «Ночного дозора» ещё больше увеличил масштаб спецэффектов и зрелищности первого фильма.","fact":"Часть финальных сцен фильма снимали с использованием реального московского городского пространства, преображённого компьютерной графикой.","wiki_en":"Day Watch (film)","wiki_ru":"Дневной Дозор (фильм)"},{"name":"9 рота","emoji":"🪖","meta":["военная драма","2005","Фёдор Бондарчук"],"description":"Группа молодых новобранцев проходит суровую подготовку в учебке перед отправкой в Афганистан, а затем оказывается на удалённой высоте, которую советскому подразделению приходится удерживать против превосходящих сил противника. Фильм Фёдора Бондарчука стал одной из самых заметных российских картин об афганской войне.","fact":"Сюжет фильма основан на реальных событиях боя за высоту 3234, произошедшего в 1988 году в Афганистане.","wiki_en":"9th Company"},{"name":"Т-34","emoji":"🪖","meta":["военная драма","2018","Алексей Сидоров"],"description":"Молодой советский танкист попадает в немецкий плен, а спустя годы его заставляют испытывать трофейный танк Т-34 против опытного немецкого экипажа, что даёт герою неожиданный шанс на дерзкий побег. Фильм Алексея Сидорова стал одним из самых кассовых российских военных боевиков.","fact":"Для съёмок фильма было построено несколько полноразмерных действующих копий танков Т-34 и немецкой техники того периода.","wiki_en":"T-34 (film)","wiki_ru":"Т-34 (фильм)"},{"name":"Движение вверх","emoji":"🏀","meta":["спортивная драма","2017","Антон Мегердичев"],"description":"Фильм воссоздаёт легендарный финал баскетбольного турнира летних Олимпийских игр 1972 года между сборными СССР и США, ставший одним из самых драматичных и обсуждаемых матчей в истории мирового баскетбола. Картина Антона Мегердичева стала одной из самых кассовых российских лент своего времени.","fact":"Финальные секунды того легендарного олимпийского матча спортивные комментаторы до сих пор регулярно вспоминают как один из самых напряжённых моментов в истории баскетбола.","wiki_en":"Going Vertical","wiki_ru":"Движение вверх (фильм)"},{"name":"Легенда №17","emoji":"🏒","meta":["спортивная драма","2013","Николай Лебедев"],"description":"Фильм рассказывает о становлении легендарного советского хоккеиста Валерия Харламова, его непростом пути в большой спорт и противостоянии со звёздной канадской сборной в исторической Суперсерии 1972 года. Биографическая драма Николая Лебедева стала одной из самых успешных российских спортивных картин.","fact":"Тренировочный лагерь для актёров, готовившихся к съёмкам хоккейных сцен, вели настоящие профессиональные хоккейные тренеры.","wiki_en":"Legend No. 17","wiki_ru":"Легенда №17"},{"name":"Викинг","emoji":"⚔️","meta":["историческая драма","2016","Андрей Кравчук"],"description":"Фильм повествует о раннем этапе правления князя Владимира Святославича, его борьбе за киевский престол и последующем судьбоносном выборе новой веры для Древней Руси. Масштабная историческая драма Андрея Кравчука стала одной из самых дорогих российских кинопостановок своего времени.","fact":"Для съёмок масштабных батальных сцен были построены декорации древнего Киева и привлечены сотни каскадёров и массовки.","wiki_en":"Viking (2016 film)"},{"name":"Сталинград","emoji":"🏚️","meta":["военная драма","2013","Фёдор Бондарчук"],"description":"Небольшая группа советских солдат закрепляется в полуразрушенном доме на подступах к Волге во время Сталинградской битвы и вместе с оставшейся там девушкой пытается удержать позицию против немецкого наступления. Фильм Фёдора Бондарчука стал одним из первых российских блокбастеров, снятых в формате IMAX 3D.","fact":"Картину выдвинули от России на «Оскар» в номинации за лучший фильм на иностранном языке.","wiki_en":"Stalingrad (2013 film)"},{"name":"Дурак","emoji":"🏚️","meta":["социальная драма","2014","Юрий Быков"],"description":"Сантехник обнаруживает в старом рабочем общежитии угрожающую обрушением трещину и в течение одной ночи пытается убедить равнодушных чиновников экстренно эвакуировать сотни жильцов, сталкиваясь со стеной коррупции и безразличия. Остросоциальная драма Юрия Быкова получила признание на международных фестивалях.","fact":"Весь фильм разворачивается в течение одной ночи практически в реальном времени, усиливая ощущение нарастающего напряжения.","wiki_en":"The Fool (2014 film)"},{"name":"Аритмия","emoji":"❤️‍🩹","meta":["драма","2017","Борис Хлебников"],"description":"Врач скорой помощи, самоотверженно спасающий пациентов, но эмоционально истощённый на работе, балансирует на грани развода с женой, тоже врачом, пытаясь сохранить и профессию, и семью одновременно. Фильм Бориса Хлебникова получил главный приз кинофестиваля «Кинотавр» и широкое признание критиков.","fact":"Многие сцены выездов скорой помощи снимали с реальными врачами-консультантами, чтобы максимально точно передать специфику их работы.","wiki_en":"Arrhythmia (film)"},{"name":"Нелюбовь","emoji":"🏚️","meta":["драма","2017","Андрей Звягинцев"],"description":"Пара, находящаяся в процессе тяжёлого развода и поглощённая взаимными обвинениями и новыми отношениями, поздно замечает, что их сын пропал из дома. Драма Андрея Звягинцева получила приз жюри Каннского кинофестиваля и номинацию на «Оскар» как лучший фильм на иностранном языке.","fact":"Фильм стал одним из самых титулованных российских фильмов на международных фестивалях за последнее десятилетие.","wiki_en":"Loveless (film)"},{"name":"Левиафан","emoji":"🐋","meta":["драма","2014","Андрей Звягинцев"],"description":"Автомеханик из небольшого приморского городка вступает в неравную борьбу с коррумпированным местным мэром, который пытается отобрать у него дом и землю, и эта тяжба постепенно разрушает всю его жизнь. Драма Андрея Звягинцева получила «Золотой глобус» и номинацию на «Оскар» за лучший фильм на иностранном языке.","fact":"Название фильма отсылает к библейскому чудовищу Левиафану и одноимённому трактату философа Томаса Гоббса о природе государственной власти.","wiki_en":"Leviathan (2014 film)"},{"name":"Елена","emoji":"🏢","meta":["драма","2011","Андрей Звягинцев"],"description":"Немолодая женщина, вышедшая замуж за обеспеченного мужчину из другого социального круга, оказывается перед трудным моральным выбором, когда её взрослый сын от первого брака остро нуждается в деньгах, а муж не намерен ему помогать. Камерная драма Андрея Звягинцева получила специальный приз программы «Особый взгляд» Каннского кинофестиваля.","fact":"Фильм был отмечен критиками за подчёркнуто сдержанную, почти документальную манеру повествования без лишней музыки и пафоса.","wiki_en":"Elena (2011 film)"},{"name":"Возвращение","emoji":"🚤","meta":["драма","2003","Андрей Звягинцев"],"description":"Двое братьев-подростков, выросшие без отца, внезапно встречают вернувшегося после долгого отсутствия отца, который увозит их в загадочную поездку к отдалённому озеру, постепенно раскрывающую сложную природу их отношений. Режиссёрский дебют Андрея Звягинцева получил главный приз «Золотой лев» Венецианского кинофестиваля.","fact":"Это редкий случай, когда полнометражный дебют режиссёра сразу получил главный приз одного из трёх крупнейших европейских кинофестивалей.","wiki_en":"The Return (2003 film)"},{"name":"Груз 200","emoji":"🚔","meta":["драма","2007","Алексей Балабанов"],"description":"В позднесоветском провинциальном городе жестокий милицейский офицер похищает девушку, и её судьба переплетается с распадом моральных норм угасающей эпохи. Мрачная и намеренно шокирующая драма Алексея Балабанова вызвала бурные споры при своём выходе за предельно жёсткое изображение эпохи позднего СССР.","fact":"Название фильма отсылает к армейскому шифру «груз 200», которым в советской системе обозначали перевозку тел погибших военнослужащих.","wiki_en":"Cargo 200 (film)","wiki_ru":"Груз 200 (фильм)"},{"name":"Жмурки","emoji":"🔫","meta":["чёрная комедия","2005","Алексей Балабанов"],"description":"Два мелких бандита из провинциального города 1990-х годов пытаются провернуть сделку с чемоданом наркотиков, но простая операция превращается в цепочку нелепых и кровавых недоразумений с участием других криминальных группировок. Чёрная комедия Алексея Балабанова гротескно высмеивает эпоху бандитских 1990-х.","fact":"В фильме собран звёздный ансамбль российских актёров, многие из которых сыграли непривычные для себя гротескные криминальные роли.","wiki_en":"Dead Man's Bluff"},{"name":"Горько!","emoji":"🥂","meta":["комедия","2013","Жора Крыжовников"],"description":"Молодая пара мечтает о скромной современной свадьбе, но родители настаивают на пышном традиционном банкете со всеми привычными атрибутами, и в итоге получившееся торжество превращается в череду комичных и неловких ситуаций. Комедия, снятая в псевдодокументальном стиле, стала одним из самых успешных российских фильмов десятилетия.","fact":"Фильм снят в стилистике любительской съёмки на свадебную камеру, что придаёт происходящему на экране эффект подлинности.","wiki_en":"Gorko!"},{"name":"Ёлки","emoji":"🎄","meta":["новогодняя комедия","2010","Тимур Бекмамбетов и др."],"description":"В канун Нового года через цепочку случайных знакомых из уст в уста передаётся послание для президента страны, и параллельно разворачивается несколько забавных новогодних историй в разных городах России. Альманах нескольких режиссёров положил начало долгоиграющей ежегодной франшизе новогодних комедий.","fact":"Успех первого фильма привёл к выходу целой серии сиквелов, каждый из которых выходил в прокат аккурат к очередному Новому году.","wiki_en":"Yolki (film)","wiki_ru":"Ёлки (фильм)"},{"name":"Самый лучший фильм","emoji":"🎬","meta":["пародийная комедия","2008","Кирилл Кузин"],"description":"Пародийная комедия построена как череда сцен-передразниваний: авторы прогоняют через себя штампы популярных российских фильмов, сериалов и рекламы, узнаваемо переигрывая известные эпизоды. Фильм собрал звёздный состав отечественных комиков и стал одним из самых кассовых российских релизов своего года.","fact":"Название и стилистика фильма пародируют серию голливудских пародийных комедий вроде «Очень страшное кино», адаптированную под российские реалии.","wiki_en":"The Best Movie"},{"name":"Любовь-морковь","emoji":"🥕","meta":["комедия","2007","Александр Стриженов"],"description":"Семейная пара, уставшая друг от друга после многих лет брака, после сеанса у экстрасенса неожиданно меняется телами и вынуждена на собственном опыте прожить день в шкуре супруга. Комедийная история о смене тел стала одной из самых популярных российских семейных комедий своего времени.","fact":"Успех фильма породил несколько сиквелов, в которых главные герои снова сталкивались с похожими магическими превращениями.","wiki_en":"Lyubov-Morkov","wiki_ru":"Любовь-морковь"},{"name":"Иван Царевич и Серый Волк","emoji":"🐺","meta":["анимация","2011","Владимир Торопчин"],"description":"Незадачливый младший царский сын Иван вместе с находчивым говорящим Серым Волком отправляется добывать Жар-птицу, чтобы спасти захворавшего отца, и по пути переживает череду комичных приключений с фольклорными персонажами. Российский мультфильм соединяет мотивы народных сказок с современным юмором.","fact":"Успех первого мультфильма положил начало целой серии сиквелов о приключениях Ивана Царевича и его волка-компаньона.","wiki_en":"Ivan Tsarevich and the Gray Wolf (film)","wiki_ru":"Иван Царевич и Серый Волк (мультфильм)"},{"name":"Три богатыря и Шамаханская царица","emoji":"🐴","meta":["анимация","2010","Сергей Глезин"],"description":"Богатыри Илья Муромец, Добрыня Никитич и Алёша Попович вместе с вечно хитрящим князем Киевским оказываются втянуты в историю с коварной Шамаханской царицей, чьи чары переворачивают привычную жизнь Киева. Один из фильмов популярной российской мультсерии о былинных богатырях.","fact":"Серия мультфильмов о трёх богатырях стала одной из самых долгоиграющих и кассовых российских анимационных франшиз.","wiki_en":"Three Bogatyrs and the Shamakhan Queen","wiki_ru":"Три богатыря и Шамаханская царица"},{"name":"Холоп","emoji":"🎩","meta":["комедия","2019","Клим Шипенко"],"description":"Избалованный богатый наследник после очередной выходки оказывается обманом помещён родными в имитацию крепостной деревни XIX века, где его заставляют жить и работать наравне с настоящими крестьянами, чтобы преподать урок скромности. Комедия Клима Шипенко стала одним из самых кассовых российских фильмов своего года.","fact":"На момент выхода это был самый кассовый российский фильм в отечественном прокате — его сборы превысили три миллиарда рублей.","wiki_en":"Serf (film)","wiki_ru":"Холоп (фильм)"},{"name":"Майор Гром: Чумной Доктор","emoji":"🦇","meta":["супергероика","2021","Олег Трофим"],"description":"Принципиальный петербургский полицейский Игорь Гром вступает в противостояние с таинственным мстителем в маске Чумного Доктора, устраивающим самосуд над городскими коррупционерами. Экранизация популярного российского комикса стала одной из первых заметных отечественных попыток в жанре супергеройского кино.","fact":"Фильм основан на серии российских комиксов издательства Bubble, выходящих с начала 2010-х годов.","wiki_en":"Major Grom: Plague Doctor"},{"name":"Притяжение","emoji":"🛸","meta":["фантастика","2017","Фёдор Бондарчук"],"description":"После крушения неопознанного летающего объекта на окраине Москвы среди перепуганных и агрессивно настроенных жителей района вспыхивают панические настроения, а дочь военного находит с инопланетным гостем неожиданный общий язык. Фантастический блокбастер Фёдора Бондарчука сочетает зрелищные спецэффекты с драмой человеческих страхов перед неизвестным.","fact":"Съёмки сцен крушения объекта проходили с использованием масштабных декораций, имитирующих реальный московский спальный район.","wiki_en":"Attraction (2017 film)"},{"name":"Аватар: Путь воды","emoji":"🌊","meta":["фантастика","2022","Джеймс Кэмерон"],"description":"Спустя годы после событий первого фильма бывший морпех Джейк Салли и его семья из клана на'ви вынуждены покинуть родной лес и искать убежища среди рифовых племён Пандоры, чтобы спастись от новой угрозы со стороны людей. Сиквел значительно расширил подводный мир планеты и вновь произвёл революцию в технологиях 3D-съёмки.","fact":"Часть подводных сцен фильма актёры снимали, действительно надолго задерживая дыхание под водой без использования акваланга.","wiki_en":"Avatar: The Way of Water"},{"name":"Дэдпул 2","emoji":"⚔️","meta":["супергероика","2018","Дэвид Литч"],"description":"Циничный и не в меру болтливый наёмник-мутант Дэдпул собирает собственную команду супергероев, чтобы защитить юного мутанта от прибывшего из будущего беспощадного солдата-киборга. Сиквел сохранил фирменный чёрный юмор оригинала и разрушение четвёртой стены, обращённое напрямую к зрителю.","fact":"Фильм известен обилием шуток, пародирующих другие супергеройские франшизы, включая киновселенные Marvel, DC и Людей Икс.","wiki_en":"Deadpool 2"},{"name":"Джокер: Безумие на двоих","emoji":"🃏","meta":["криминальная драма","2024","Тодд Филлипс"],"description":"Артур Флек, уже находясь под стражей в психиатрической лечебнице Аркхэм, встречает пациентку Харли Куинзель, с которой его связывает взаимное притяжение и общее презрение к окружающему миру. Сиквел оскароносного фильма 2019 года неожиданно превратил драму о происхождении злодея в мюзикл.","fact":"В отличие от первого фильма, значительная часть сюжета сиквела разворачивается в формате музыкальных номеров с участием главных героев.","wiki_en":"Joker: Folie à Deux"},{"name":"Круэлла","emoji":"🐶","meta":["криминальная драма","2021","Крэйг Гиллеспи"],"description":"Фильм рассказывает предысторию знаменитой диснеевской злодейки — талантливой, но непризнанной модельерши Эстеллы, которая в панковском Лондоне 1970-х постепенно превращается в дерзкую и мстительную Круэллу де Виль. Приквел о происхождении классического анимационного антагониста сделал упор на яркую эстетику эпохи панк-рока.","fact":"Костюмы создавала Дженни Биван, получившая за них «Оскар»: она вдохновлялась модой лондонской панк-сцены 1970-х годов.","wiki_en":"Cruella (film)"},{"name":"Крепкий орешек 2","emoji":"✈️","meta":["боевик","1990","Ренни Харлин"],"description":"Полицейский Джон Макклейн снова оказывается не в том месте не в то время: на этот раз в аэропорту, который захватывают вооружённые наёмники, угрожающие сотням пассажиров в кружащих над землёй самолётах. Сиквел культового боевика перенёс действие из небоскрёба в масштабы целого аэропорта.","fact":"Действие фильма разворачивается в канун Рождества, как и в первом фильме серии, что стало фирменной традицией всей франшизы.","wiki_en":"Die Hard 2"},{"name":"Крепкий орешек 3: Возмездие","emoji":"💣","meta":["боевик","1995","Джон Мактирнан"],"description":"Загадочный террорист вынуждает измотанного полицейского Джона Макклейна решать смертельно опасные головоломки по всему Нью-Йорку, пока тот не понимает, что все эти испытания — лишь отвлекающий манёвр для куда более масштабного преступления. Третий фильм серии вернул режиссёра оригинального «Крепкого орешка».","fact":"Партнёром Макклейна в этом фильме впервые в серии стал гражданский по имени Зевс, сыгранный Сэмюэлом Л. Джексоном.","wiki_en":"Die Hard with a Vengeance"},{"name":"Люди в чёрном 2","emoji":"👽","meta":["фантастика","2002","Барри Зонненфельд"],"description":"Агент Джей возвращает в строй бывшего напарника Кея, которому когда-то стёрли память о службе, чтобы вместе остановить новую опасную пришелицу, охотящуюся за спрятанным на Земле артефактом. Сиквел продолжил комедийно-фантастическую историю тайных защитников планеты от инопланетных угроз.","fact":"В сиквеле снова появляются любимцы зрителей — инопланетные червяки, которым здесь досталось заметно больше экранного времени.","wiki_en":"Men in Black II"},{"name":"Годзилла против Конга","emoji":"🦖","meta":["фантастика","2021","Адам Уингард"],"description":"Два легендарных гигантских монстра — ящероподобная Годзилла и огромная горилла Конг — сталкиваются в эпической схватке друг с другом, пока люди пытаются понять истинную причину внезапной агрессии Годзиллы. Фильм объединил две крупные кинофраншизы студии Legendary в рамках единой монстровселенной MonsterVerse.","fact":"Ради схватки с Годзиллой Конга заметно «подрастили»: в этой монстровселенной он куда крупнее, чем в собственном фильме про Остров черепа.","wiki_en":"Godzilla vs. Kong"},{"name":"Мир юрского периода","emoji":"🦕","meta":["фантастика","2015","Колин Треворроу"],"description":"Спустя два десятилетия после событий первого «Парка юрского периода» на острове работает полноценный динозавровый тематический парк для туристов, пока учёные не выводят нового генетически модифицированного гибридного хищника, оказавшегося куда опаснее, чем ожидалось. Перезапуск франшизы стал одним из самых кассовых фильмов своего года.","fact":"Фильм установил рекорд по кассовым сборам в первый уикенд проката на момент своего выхода в 2015 году.","wiki_en":"Jurassic World"},{"name":"Не смотрите наверх","emoji":"☄️","meta":["сатирическая комедия","2021","Адам Маккей"],"description":"Два малоизвестных астронома обнаруживают комету, которая неминуемо уничтожит Землю, и пытаются достучаться до равнодушных политиков и медиа, поглощённых собственными сиюминутными интересами, а не надвигающейся катастрофой. Сатирическая комедия со звёздным составом высмеивает современное общество потребления информации.","fact":"Несмотря на фантастический сюжет, фильм задумывался создателями как метафора равнодушия общества к изменению климата.","wiki_en":"Don't Look Up"},{"name":"Зелёная книга","emoji":"🚗","meta":["драма","2018","Питер Фаррелли"],"description":"Грубоватый вышибала из Бронкса устраивается водителем и телохранителем к утончённому чернокожему пианисту, отправляющемуся в турне по расистскому Югу США 1960-х годов, и за время долгой поездки между ними завязывается неожиданная дружба. Фильм получил «Оскар» за лучший фильм и основан на реальной истории.","fact":"Название фильма отсылает к настоящему справочнику «Зелёная книга», который в те годы помогал чернокожим путешественникам находить безопасные для них заведения на Юге.","wiki_en":"Green Book (film)","wiki_ru":"Зелёная книга (фильм)"},{"name":"1917","emoji":"🪖","meta":["военная драма","2019","Сэм Мендес"],"description":"Двум молодым британским солдатам Первой мировой войны поручают срочно доставить приказ об отмене атаки в соседний полк, чтобы предотвратить гибель тысяч товарищей, попавших в подготовленную немцами ловушку. Фильм Сэма Мендеса снят так, чтобы создавать иллюзию единого непрерывного кадра на протяжении почти всего повествования.","fact":"Ради эффекта непрерывной съёмки создатели тщательно репетировали сложнейшие сцены с движущейся камерой на протяжении многих месяцев.","wiki_en":"1917 (2019 film)"},{"name":"Марсианин","emoji":"🚀","meta":["фантастика","2015","Ридли Скотт"],"description":"Астронавт по случайности оставлен командой на Марсе после экстренной эвакуации во время песчаной бури и вынужден в одиночку выживать на враждебной планете, полагаясь на научные знания и находчивость, пока не появится шанс на спасение. Экранизация романа Энди Вейра прославилась достоверным подходом к научным деталям выживания в космосе.","fact":"Сценаристы и консультанты фильма сотрудничали с настоящими специалистами NASA, чтобы максимально реалистично показать методы выживания героя.","wiki_en":"The Martian (film)"},{"name":"Гравитация","emoji":"🛰️","meta":["фантастика","2013","Альфонсо Куарон"],"description":"Во время работы в открытом космосе шквал обломков уничтожает корабль, и астронавт-новичок остаётся на орбите одна, вынужденная бороться за выживание в невесомости с быстро убывающим запасом кислорода. Фильм Альфонсо Куарона поразил зрителей новаторскими длинными операторскими планами и реалистичной визуализацией космоса.","fact":"Для создания иллюзии невесомости актёров помещали в специальную конструкцию с управляемым освещением, имитирующим условия открытого космоса.","wiki_en":"Gravity (2013 film)"},{"name":"Крик","emoji":"🔪","meta":["ужасы","1996","Уэс Крейвен"],"description":"В тихом американском городке начинается серия жестоких убийств, которые совершает загадочный маньяк в маске призрака, хорошо разбирающийся в законах жанра классических слэшеров и постоянно испытывающий героев на знание этих самых правил. Фильм Уэса Крейвена возродил жанр слэшер-хорроров благодаря самоироничному подходу к штампам жанра.","fact":"Маска убийцы из этого фильма стала одним из самых узнаваемых и растиражированных образов в поп-культуре, включая костюмы на Хэллоуин.","wiki_en":"Scream (1996 film)"},{"name":"Хэллоуин","emoji":"🔪","meta":["ужасы","1978","Джон Карпентер"],"description":"Спустя годы после совершённого в детстве убийства сестры психически нестабильный Майкл Майерс сбегает из лечебницы и возвращается в родной город в канун Хэллоуина, где начинает охотиться на местных подростков. Малобюджетный фильм Джона Карпентера считается одним из основателей жанра слэшер-хорроров.","fact":"Знаменитая тревожная тема фильма написана самим Джоном Карпентером и стала одной из самых узнаваемых мелодий в истории хоррора.","wiki_en":"Halloween (1978 film)"},{"name":"Пятница 13-е","emoji":"🏕️","meta":["ужасы","1980","Шон Каннингем"],"description":"Группа молодых вожатых, готовящих к открытию заброшенный после трагедии летний лагерь, одну за другой становится жертвами неизвестного убийцы, мстящего за давнюю гибель ребёнка на этом самом озере. Малобюджетный фильм Шона Каннингема положил начало одной из самых долгоживущих хоррор-франшиз в истории кино.","fact":"Джейсон Вурхиз, ставший символом франшизы, в первом фильме появляется лишь мельком, а его знаменитая хоккейная маска возникнет только в третьей части.","wiki_en":"Friday the 13th (1980 film)"},{"name":"Кошмар на улице Вязов","emoji":"🧤","meta":["ужасы","1984","Уэс Крейвен"],"description":"Обгоревший маньяк в свитере в красно-зелёную полоску и с когтями вместо пальцев преследует подростков одного и того же квартала прямо в их снах, откуда его жертвы уже не могут проснуться живыми. Фильм Уэса Крейвена подарил жанру хоррора одного из самых узнаваемых злодеев — Фредди Крюгера.","fact":"Актёр Роберт Инглунд, сыгравший Фредди Крюгера, впоследствии воплощал этого персонажа почти во всех фильмах и сериалах франшизы на протяжении десятилетий.","wiki_en":"A Nightmare on Elm Street"},{"name":"Пила","emoji":"🩸","meta":["ужасы","2004","Джеймс Ван"],"description":"Два незнакомых друг с другом мужчины приходят в сознание прикованными цепями в грязной ванной комнате и обнаруживают, что стали участниками смертельной игры загадочного маньяка, испытывающего своих жертв изощрёнными моральными и физическими ловушками. Малобюджетный дебютный фильм Джеймса Вана породил целую франшизу хорроров о ловушках-головоломках.","fact":"Фильм был снят всего за восемнадцать дней и с крайне скромным бюджетом, что не помешало ему собрать в разы больше денег в мировом прокате.","wiki_en":"Saw (2004 film)"},{"name":"Оно","emoji":"🎈","meta":["ужасы","2017","Энди Мускетти"],"description":"Группа детей-изгоев из провинциального американского городка объединяется, чтобы противостоять древнему злу, принимающему облик их худших страхов, чаще всего являясь им в образе зловещего клоуна Пеннивайза. Экранизация романа Стивена Кинга стала одним из самых кассовых фильмов ужасов в истории кино.","fact":"Образ клоуна Пеннивайза в исполнении Билла Скарсгарда стал одним из самых узнаваемых киновоплощений злодеев Стивена Кинга.","wiki_en":"It (2017 film)"},{"name":"Тихое место","emoji":"🤫","meta":["ужасы","2018","Джон Красински"],"description":"Семья выживает в мире, захваченном слепыми, но обладающими сверхчувствительным слухом существами, и вынуждена общаться жестами и передвигаться почти в полной тишине, чтобы не привлечь их внимания. Фильм Джона Красински построен на непривычном для хоррора минимуме диалогов и звуков.","fact":"Значительная часть диалогов в фильме передаётся с помощью американского жестового языка вместо привычной речи.","wiki_en":"A Quiet Place"},{"name":"Заклятие","emoji":"🕯️","meta":["ужасы","2013","Джеймс Ван"],"description":"Семейная пара переезжает в старый фермерский дом в Род-Айленде, где начинают происходить всё более пугающие паранормальные явления, вынуждающие их обратиться к известным исследователям потустороннего — супругам Уорренам. Фильм Джеймса Вана основан на одном из реальных дел этой пары и положил начало обширной хоррор-вселенной.","fact":"Взрослый рейтинг R фильм получил не за кровь и жестокость, которых в нём почти нет, а за общую пугающую атмосферу.","wiki_en":"The Conjuring"},{"name":"Астрал","emoji":"👻","meta":["ужасы","2010","Джеймс Ван"],"description":"После загадочного падения мальчика в коме его семья сталкивается со всё более пугающими паранормальными явлениями в доме и обращается за помощью к медиуму, которая объясняет происходящее связью ребёнка с потусторонним миром, называемым Астралом. Малобюджетный фильм Джеймса Вана стал одним из самых прибыльных хорроров своего времени.","fact":"Именно здесь появляется медиум Элис Рейнир, которая затем стала центральной фигурой всей франшизы, включая приквелы.","wiki_en":"Insidious (film)"},{"name":"Прочь","emoji":"🌀","meta":["хоррор-триллер","2017","Джордан Пил"],"description":"Молодой чернокожий фотограф едет знакомиться с семьёй белой девушки за город и постепенно замечает всё больше странностей в поведении хозяев дома и их гостей, скрывающих зловещую тайну. Режиссёрский дебют комика Джордана Пила соединил жанр хоррора с острой социальной сатирой на расовые предрассудки.","fact":"Фильм получил «Оскар» за лучший оригинальный сценарий, что стало редкостью для картины, формально относящейся к жанру ужасов.","wiki_en":"Get Out"},{"name":"Чикаго","emoji":"🎷","meta":["мюзикл","2002","Роб Маршалл"],"description":"Начинающая певица и уже известная звезда варьете, обе обвинённые в убийстве, соперничают за внимание публики и ловкого адвоката в мире джазового Чикаго 1920-х годов, где скандал легко превращается в билет к славе. Экранизация бродвейского мюзикла получила «Оскар» за лучший фильм и вернула жанр киномюзикла на большие экраны.","fact":"Музыкальные номера фильма выстроены как воображаемые выступления, разворачивающиеся в сознании главной героини параллельно с реальными событиями.","wiki_en":"Chicago (2002 film)"},{"name":"Мулен Руж!","emoji":"🎭","meta":["мюзикл","2001","Баз Лурман"],"description":"Молодой английский поэт в богемном Париже конца XIX века влюбляется в звезду знаменитого кабаре «Мулен Руж», и их роман разворачивается на фоне ярких музыкальных номеров, соединяющих классические мелодии с современными поп-хитами. Фильм База Лурмана отличается динамичным монтажом и эксцентричной визуальной эстетикой.","fact":"Саундтрек фильма смешивает классические оперные партии с кавер-версиями современных поп-песен разных десятилетий, включённых в единые музыкальные номера.","wiki_en":"Moulin Rouge!"},{"name":"Богемская рапсодия","emoji":"🎤","meta":["музыкальная биография","2018","Брайан Сингер"],"description":"Фильм прослеживает путь группы Queen от первых выступлений в небольших клубах до статуса одной из величайших рок-групп в мире, уделяя особое внимание яркой и противоречивой личности фронтмена Фредди Меркьюри. Байопик о легендарной группе завершается воссозданием их исторического выступления на благотворительном концерте Live Aid.","fact":"Актёр Рами Малек получил «Оскар» за роль Фредди Меркьюри, для которой он долго готовился, изучая его сценическую пластику и манеру пения.","wiki_en":"Bohemian Rhapsody (film)"},{"name":"Рокетмен","emoji":"🕶️","meta":["музыкальная биография","2019","Декстер Флетчер"],"description":"Биографический мюзикл рассказывает о пути музыканта Элтона Джона от застенчивого мальчика из пригорода Лондона до одной из самых экстравагантных звёзд мировой поп-сцены через призму его собственных знаменитых песен. В отличие от многих музыкальных байопиков, фильм открыто сочетает реальные биографические события с фантазийными музыкальными номерами.","fact":"Все вокальные партии в фильме спел сам Тэрон Эджертон, а не оригинальный исполнитель этих песен.","wiki_en":"Rocketman (film)"},{"name":"Отверженные","emoji":"🇫🇷","meta":["мюзикл","2012","Том Хупер"],"description":"Бывший каторжник Жан Вальжан, нарушивший условия досрочного освобождения, пытается начать новую честную жизнь, но его неотступно преследует принципиальный полицейский инспектор Жавер, а действие разворачивается на фоне народных волнений в Париже XIX века. Экранизация знаменитого мюзикла по роману Виктора Гюго примечательна тем, что все песни актёры пели вживую прямо во время съёмок.","fact":"Энн Хэтэуэй получила «Оскар» за роль Фантины, а её главную песню сняли одним непрерывным крупным планом.","wiki_en":"Les Misérables (2012 film)"}];
